130→/**
131→ * POST /api/collections/[id]/tools
132→ * Add a tool to a collection
133→ */
134→export async function POST(
135→  request: NextRequest,
136→  context: RouteContext
137→): Promise<NextResponse<ApiResponse>> {
138→  const requestId = crypto.randomUUID();
139→  const { id: collectionId } = await context.params;
140→
141→  try {
142→    // Check authentication
143→    const session = await auth.api.getSession({
144→      headers: await headers(),
145→    });
146→
147→    if (!session) {
148→      return NextResponse.json(
149→        {
150→          success: false,
151→          error: { code: 'UNAUTHORIZED', message: 'Authentication required' },
152→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
153→        },
154→        { status: 401 }
155→      );
156→    }
157→
158→    // Verify collection exists and user owns it
159→    const collection = await prisma.collection.findUnique({
160→      where: { id: collectionId },
161→      include: { _count: { select: { tools: true } } },
162→    });
163→
164→    if (!collection) {
165→      return NextResponse.json(
166→        {
167→          success: false,
168→          error: { code: 'NOT_FOUND', message: 'Collection not found' },
169→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
170→        },
171→        { status: 404 }
172→      );
173→    }
174→
175→    if (collection.userId !== session.user.id) {
176→      return NextResponse.json(
177→        {
178→          success: false,
179→          error: { code: 'FORBIDDEN', message: 'Access denied' },
180→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
181→        },
182→        { status: 403 }
183→      );
184→    }
185→
186→    // Parse and validate request body
187→    const body = await request.json();
188→    const parseResult = AddToolToCollectionSchema.safeParse(body);
189→
190→    if (!parseResult.success) {
191→      return NextResponse.json(
192→        {
193→          success: false,
194→          error: {
195→            code: 'VALIDATION_ERROR',
196→            message: 'Invalid request body',
197→            details: { errors: parseResult.error.flatten().fieldErrors },
198→          },
199→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
200→        },
201→        { status: 400 }
202→      );
203→    }
204→
205→    const { toolId, note, position } = parseResult.data;
206→
207→    // Check tool limit
208→    if (collection._count.tools >= COLLECTION_LIMITS.MAX_TOOLS_PER_COLLECTION) {
209→      return NextResponse.json(
210→        {
211→          success: false,
212→          error: {
213→            code: 'LIMIT_EXCEEDED',
214→            message: `Maximum ${COLLECTION_LIMITS.MAX_TOOLS_PER_COLLECTION} tools per collection`,
215→          },
216→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
217→        },
218→        { status: 400 }
219→      );
220→    }
221→
222→    // Verify tool exists
223→    const tool = await prisma.tool.findUnique({
224→      where: { id: toolId },
225→      include: {
226→        package: {
227→          select: {
228→            id: true,
229→            npmPackageName: true,
230→            category: true,
231→          },
232→        },
233→      },
234→    });
235→
236→    if (!tool) {
237→      return NextResponse.json(
238→        {
239→          success: false,
240→          error: { code: 'NOT_FOUND', message: 'Tool not found' },
241→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
242→        },
243→        { status: 404 }
244→      );
245→    }
246→
247→    // Check if tool is already in collection
248→    const existingEntry = await prisma.collectionTool.findUnique({
249→      where: {
250→        collectionId_toolId: {
251→          collectionId,
252→          toolId,
253→        },
254→      },
255→    });
256→
257→    if (existingEntry) {
258→      return NextResponse.json(
259→        {
260→          success: false,
261→          error: { code: 'DUPLICATE_TOOL', message: 'Tool is already in this collection' },
262→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
263→        },
264→        { status: 409 }
265→      );
266→    }
267→
268→    // Get max position if not specified
269→    const maxPosition =
270→      position ??
271→      (await prisma.collectionTool.count({
272→        where: { collectionId },
273→      }));
274→
275→    // Add tool to collection
276→    const collectionTool = await prisma.collectionTool.create({
277→      data: {
278→        collectionId,
279→        toolId,
280→        note: note || null,
281→        position: maxPosition,
282→      },
283→    });
284→
285→    // Log activity (fire-and-forget)
286→    logActivity({
287→      userId: session.user.id,
288→      type: 'COLLECTION_TOOL_ADDED',
289→      targetName: collection.name,
290→      targetType: 'collection',
291→      collectionId,
292→      toolId,
293→      metadata: { toolName: tool.name },
294→    });
295→
296→    return NextResponse.json(
297→      {
298→        success: true,
299→        data: {
300→          id: collectionTool.id,
301→          toolId: collectionTool.toolId,
302→          position: collectionTool.position,
303→          note: collectionTool.note,
304→          addedAt: collectionTool.addedAt,
305→          tool: {
306→            id: tool.id,
307→            name: tool.name,
308→            description: tool.description,
309→            package: tool.package,
310→          },
311→        },
312→        meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
313→      },
314→      { status: 201 }
315→    );
316→  } catch (error) {
317→    console.error('[API Error] POST /api/collections/[id]/tools:', error);
318→    return NextResponse.json(
319→      {
320→        success: false,
321→        error: { code: 'INTERNAL_ERROR', message: 'Failed to add tool to collection' },
322→        meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
323→      },
324→      { status: 500 }
325→    );
326→  }
327→}
