 25→/**
 26→ * Wrap a promise with a timeout
 27→ */
 28→function withTimeout<T>(promise: Promise<T>, ms: number, errorMessage: string): Promise<T> {
 29→  return Promise.race([
 30→    promise,
 31→    new Promise<T>((_, reject) => setTimeout(() => reject(new Error(errorMessage)), ms)),
 32→  ]);
 33→}
