 53→/**
 54→ * Handle MCP tools/list request
 55→ */
 56→export async function handleToolsList(
 57→  collectionId: string,
 58→  requestId: JsonRpcId
 59→): Promise<JsonRpcResponse> {
 60→  try {
 61→    const collection = await withTimeout(
 62→      prisma.collection.findUnique({
 63→        where: { id: collectionId },
 64→        include: {
 65→          tools: {
 66→            include: { tool: { include: { package: true } } },
 67→            orderBy: { position: 'asc' },
 68→          },
 69→          bridgeTools: true,
 70→          user: {
 71→            include: {
 72→              bridgeConnection: true,
 73→            },
 74→          },
 75→        },
 76→      }),
 77→      DB_TIMEOUT_MS,
 78→      'Database query timed out'
 79→    );
 80→
 81→    // Convert registry tools to MCP format
 82→    const registryTools = collection?.tools.map((ct) => convertToMcpTool(ct.tool)) ?? [];
 83→
 84→    // Convert bridge tools to MCP format
 85→    const bridgeTools: ReturnType<typeof convertBridgeToolToMcp>[] = [];
 86→
 87→    if (collection?.bridgeTools.length && collection.user.bridgeConnection) {
 88→      const bridgeConnection = collection.user.bridgeConnection;
 89→      const availableBridgeTools = (bridgeConnection.tools as unknown as BridgeTool[]) || [];
 90→
 91→      // Only include bridge tools if bridge is connected
 92→      if (bridgeConnection.status === 'connected') {
 93→        for (const collectionBridgeTool of collection.bridgeTools) {
 94→          // Find the tool definition from the bridge connection
 95→          const bridgeTool = availableBridgeTools.find(
 96→            (bt) =>
 97→              bt.serverId === collectionBridgeTool.serverId &&
 98→              bt.name === collectionBridgeTool.toolName
 99→          );
100→
101→          if (bridgeTool) {
102→            bridgeTools.push(convertBridgeToolToMcp(bridgeTool, collectionBridgeTool.displayName));
103→          }
104→        }
105→      }
106→    }
107→
108→    return {
109→      jsonrpc: '2.0',
110→      id: requestId,
111→      result: { tools: [...registryTools, ...bridgeTools] },
112→    };
113→  } catch (error) {
114→    console.error('[MCP tools/list] Error:', error);
115→    return {
116→      jsonrpc: '2.0',
117→      id: requestId,
118→      error: { code: -32603, message: error instanceof Error ? error.message : 'Internal error' },
119→    };
120→  }
121→}
