158→/**
159→ * POST /api/mcp/[username]/[slug]/http
160→ * Streamable HTTP transport - JSON-RPC over HTTP
161→ */
162→async function handleHttpTransport(
163→  request: NextRequest,
164→  collectionId: string,
165→  collectionName: string,
166→  isOwner: boolean,
167→  trackingCtx?: TrackingContext
168→): Promise<NextResponse> {
169→  let body: JsonRpcRequest;
170→  try {
171→    body = await request.json();
172→  } catch {
173→    return NextResponse.json(
174→      { jsonrpc: '2.0', error: { code: -32700, message: 'Parse error' }, id: null },
175→      { status: 400 }
176→    );
177→  }
178→
179→  const headerEnvVars = extractEnvVarsFromHeaders(request);
180→  const response = await processJsonRpcRequest(
181→    collectionId,
182→    collectionName,
183→    body,
184→    isOwner,
185→    trackingCtx,
186→    Object.keys(headerEnvVars).length > 0 ? headerEnvVars : undefined
187→  );
188→  return NextResponse.json(response);
189→}
