286→/**
287→ * POST /api/mcp/[username]/[slug]/[transport]
288→ * MCP JSON-RPC endpoint for tool execution
289→ */
290→export async function POST(request: NextRequest, context: RouteContext): Promise<Response> {
291→  const startTime = Date.now();
292→  let authResult: Awaited<ReturnType<typeof authenticateRequest>> | null = null;
293→
294→  try {
295→    const { username, slug, transport } = await context.params;
296→
297→    if (transport !== 'http' && transport !== 'sse') {
298→      return NextResponse.json(
299→        {
300→          jsonrpc: '2.0',
301→          error: { code: -32001, message: `Invalid transport: ${transport}` },
302→          id: null,
303→        },
304→        { status: 400 }
305→      );
306→    }
307→
308→    // Authenticate the request
309→    authResult = await authenticateRequest();
310→
311→    // Check if auth is required
312→    if (REQUIRE_AUTH && !authResult.authenticated) {
313→      return NextResponse.json(
314→        {
315→          jsonrpc: '2.0',
316→          error: { code: -32000, message: authResult.error || 'Authentication required' },
317→          id: null,
318→        },
319→        { status: 401 }
320→      );
321→    }
322→
323→    // Check scope if authenticated
324→    if (authResult.authenticated && !hasScope(authResult, API_KEY_SCOPES.MCP_EXECUTE)) {
325→      return NextResponse.json(
326→        {
327→          jsonrpc: '2.0',
328→          error: { code: -32000, message: 'Missing required scope: mcp:execute' },
329→          id: null,
330→        },
331→        { status: 403 }
332→      );
333→    }
334→
335→    // Rate limit if authenticated via API key
336→    if (authResult.authenticated && authResult.apiKeyId) {
337→      const rateLimitResult = await checkApiKeyRateLimit(
338→        authResult.apiKeyId,
339→        authResult.tier || 'FREE'
340→      );
341→
342→      if (!rateLimitResult.allowed) {
343→        return createRateLimitResponse(rateLimitResult);
344→      }
345→    }
346→
347→    // Log warning for unauthenticated requests (soft launch)
348→    if (!authResult.authenticated && !REQUIRE_AUTH) {
349→      console.warn(
350→        `[MCP] Unauthenticated request to /${username}/${slug}/${transport} - ` +
351→          'API key authentication will be required in a future update'
352→      );
353→    }
354→
355→    // First, find the user by username
356→    const user = await getUserByUsername(username);
357→
358→    if (!user) {
359→      return NextResponse.json(
360→        {
361→          jsonrpc: '2.0',
362→          error: {
363→            code: -32001,
364→            message: `User '${username}' not found. Check the username in your MCP endpoint URL.`,
365→          },
366→          id: null,
367→        },
368→        { status: 404 }
369→      );
370→    }
371→
372→    // Then find the collection by user ID and slug/ID
373→    const collection = await getCollectionByUserIdAndSlugOrId(user.id, slug);
374→
375→    if (!collection) {
376→      return NextResponse.json(
377→        {
378→          jsonrpc: '2.0',
379→          error: {
380→            code: -32001,
381→            message: `Collection '${slug}' not found for user '${username}'.`,
382→          },
383→          id: null,
384→        },
385→        { status: 404 }
386→      );
387→    }
388→
389→    // Authorization check:
390→    // - Owners can always access their own collections (public or private)
391→    // - Non-owners can access PUBLIC collections with their own env vars
392→    const isOwner = authResult.userId === collection.userId;
393→
394→    if (!isOwner) {
395→      if (!collection.isPublic) {
396→        // Private collection, not the owner - don't reveal existence
397→        return NextResponse.json(
398→          { jsonrpc: '2.0', error: { code: -32001, message: 'Collection not found' }, id: null },
399→          { status: 404 }
400→        );
401→      }
402→      // Public collection - non-owners can access but must provide their own env vars
403→      // The env vars are validated per-tool in handleToolsCall
404→    }
405→
406→    // Build tracking context for execution event tracking
407→    const trackingCtx: TrackingContext = {
408→      userId: authResult.userId ?? undefined,
409→      apiKeyId: authResult.apiKeyId ?? undefined,
410→      collectionId: collection.id,
411→      source: transport === 'sse' ? 'mcp_sse' : 'mcp_http',
412→    };
413→
414→    let response: Response;
415→    if (transport === 'sse') {
416→      response = await handleSseTransport(
417→        request,
418→        collection.id,
419→        collection.name,
420→        isOwner,
421→        trackingCtx
422→      );
423→    } else {
424→      response = await handleHttpTransport(
425→        request,
426→        collection.id,
427→        collection.name,
428→        isOwner,
429→        trackingCtx
430→      );
431→    }
432→
433→    // Track usage for authenticated requests
434→    if (authResult.authenticated && authResult.userId) {
435→      const clientMeta = await getClientMetadata();
436→      trackUsage({
437→        apiKeyId: authResult.apiKeyId,
438→        userId: authResult.userId,
439→        endpoint: `/api/mcp/${username}/${slug}/${transport}`,
440→        method: 'POST',
441→        statusCode: response.status,
442→        latencyMs: Date.now() - startTime,
443→        resourceType: 'mcp',
444→        resourceId: collection.id,
445→        userAgent: clientMeta.userAgent,
446→        ipAddress: clientMeta.ipAddress,
447→      });
448→    }
449→
450→    // Add rate limit headers for authenticated requests
451→    if (authResult.authenticated && authResult.apiKeyId) {
452→      const rateLimitResult = await checkApiKeyRateLimit(
453→        authResult.apiKeyId,
454→        authResult.tier || 'FREE'
455→      );
456→      const headers = getRateLimitHeaders(rateLimitResult);
457→      for (const [key, value] of Object.entries(headers)) {
458→        response.headers.set(key, value);
459→      }
460→    }
461→
462→    return response;
463→  } catch (error) {
464→    console.error('[MCP POST] Error:', error);
465→    const message = error instanceof Error ? error.message : 'Internal server error';
466→
467→    // Track error for authenticated requests
468→    if (authResult?.authenticated && authResult.userId) {
469→      const { username, slug, transport } = await context.params;
470→      const clientMeta = await getClientMetadata();
471→      trackUsage({
472→        apiKeyId: authResult.apiKeyId,
473→        userId: authResult.userId,
474→        endpoint: `/api/mcp/${username}/${slug}/${transport}`,
475→        method: 'POST',
476→        statusCode: 500,
477→        latencyMs: Date.now() - startTime,
478→        resourceType: 'mcp',
479→        errorCode: 'INTERNAL_ERROR',
480→        errorMessage: message,
481→        userAgent: clientMeta.userAgent,
482→        ipAddress: clientMeta.ipAddress,
483→      });
484→    }
485→
486→    return NextResponse.json(
487→      { jsonrpc: '2.0', error: { code: -32603, message }, id: null },
488→      { status: 500 }
489→    );
490→  }
491→}
