 43→/**
 44→ * Wrap a promise with a timeout
 45→ */
 46→function withTimeout<T>(promise: Promise<T>, ms: number, errorMessage: string): Promise<T> {
 47→  return Promise.race([
 48→    promise,
 49→    new Promise<T>((_, reject) => setTimeout(() => reject(new Error(errorMessage)), ms)),
 50→  ]);
 51→}
