 87→/**
 88→ * Process a JSON-RPC request and return the response
 89→ */
 90→async function processJsonRpcRequest(
 91→  collectionId: string,
 92→  collectionName: string,
 93→  body: JsonRpcRequest,
 94→  isOwner: boolean,
 95→  trackingCtx?: TrackingContext
 96→): Promise<JsonRpcResponse> {
 97→  const requestId = body.id ?? null;
 98→
 99→  switch (body.method) {
100→    case 'initialize':
101→      return handleInitialize(collectionName, requestId);
102→
103→    case 'tools/list':
104→      return await handleToolsList(collectionId, requestId);
105→
106→    case 'tools/call': {
107→      const params = body.params as {
108→        name: string;
109→        arguments?: Record<string, unknown>;
110→        env?: Record<string, string>;
111→      };
112→
113→      // For non-owners, use caller-provided env vars (or empty if not provided)
114→      // For owners, callerEnvVars is undefined so handleToolsCall uses stored env vars
115→      const callerEnvVars = isOwner ? undefined : params.env || {};
116→
117→      return await handleToolsCall(collectionId, params, requestId, callerEnvVars, trackingCtx);
118→    }
119→
120→    case 'notifications/initialized':
121→    case 'ping':
122→      return { jsonrpc: '2.0', id: requestId, result: {} };
123→
124→    default:
125→      return {
126→        jsonrpc: '2.0',
127→        id: requestId,
128→        error: { code: -32601, message: `Method not found: ${body.method}` },
129→      };
130→  }
131→}
