  1→/**
  2→ * Executor Resolution Logic
  3→ *
  4→ * Handles the cascade resolution for hot-swappable executors:
  5→ * Agent Config → Collection Config → System Default
  6→ */
  7→
  8→import { executePackage } from '@tpmjs/package-executor';
  9→import type {
 10→  ExecuteToolRequest,
 11→  ExecuteToolResponse,
 12→  ExecutorConfig,
 13→  ExecutorHealthResponse,
 14→} from '@tpmjs/types/executor';
 15→
 16→const DEFAULT_TIMEOUT = 300000; // 5 minutes for custom executors
 17→
 18→/**
 19→ * Resolve executor configuration using cascade:
 20→ * Agent Config → Collection Config → System Default
 21→ *
 22→ * @param agentConfig - Executor config from Agent (highest priority)
 23→ * @param collectionConfig - Executor config from Collection (medium priority)
 24→ * @returns Resolved executor configuration
 25→ */
 26→export function resolveExecutorConfig(
 27→  agentConfig: ExecutorConfig | null | undefined,
 28→  collectionConfig: ExecutorConfig | null | undefined
 29→): ExecutorConfig {
 30→  // Agent config takes precedence
 31→  if (agentConfig && agentConfig.type !== 'default') {
 32→    return agentConfig;
 33→  }
 34→
 35→  // Fall back to collection config
 36→  if (collectionConfig && collectionConfig.type !== 'default') {
 37→    return collectionConfig;
 38→  }
 39→
 40→  // System default
 41→  return { type: 'default' };
 42→}
 43→
 44→/**
 45→ * Parse executor config from database JSON
 46→ * Handles null/undefined and validates the shape
 47→ */
 48→export function parseExecutorConfig(
 49→  executorType: string | null | undefined,
 50→  executorConfig: unknown
 51→): ExecutorConfig | null {
 52→  if (!executorType) {
 53→    return null;
 54→  }
 55→
 56→  if (executorType === 'default') {
 57→    return { type: 'default' };
 58→  }
 59→
 60→  if (executorType === 'custom_url' && executorConfig && typeof executorConfig === 'object') {
 61→    const config = executorConfig as { url?: string; apiKey?: string };
 62→    if (config.url && typeof config.url === 'string') {
 63→      return {
 64→        type: 'custom_url',
 65→        url: config.url,
 66→        apiKey: typeof config.apiKey === 'string' ? config.apiKey : undefined,
 67→      };
 68→    }
 69→  }
 70→
 71→  return null;
 72→}
 73→
 74→/**
 75→ * Execute a tool using a custom URL executor
 76→ */
 77→async function executeWithCustomUrl(
 78→  url: string,
 79→  apiKey: string | undefined,
 80→  request: ExecuteToolRequest,
 81→  timeout: number = DEFAULT_TIMEOUT
 82→): Promise<ExecuteToolResponse> {
 83→  const startTime = Date.now();
 84→
 85→  const headers: Record<string, string> = {
 86→    'Content-Type': 'application/json',
 87→  };
 88→
 89→  if (apiKey) {
 90→    headers.Authorization = `Bearer ${apiKey}`;
 91→  }
 92→
 93→  try {
 94→    const controller = new AbortController();
 95→    const timeoutId = setTimeout(() => controller.abort(), timeout);
 96→
 97→    const response = await fetch(`${url}/execute-tool`, {
 98→      method: 'POST',
 99→      headers,
100→      body: JSON.stringify(request),
101→      signal: controller.signal,
102→    });
103→
104→    clearTimeout(timeoutId);
105→
106→    const executionTimeMs = Date.now() - startTime;
107→
108→    if (!response.ok) {
109→      const errorData = (await response.json().catch(() => ({ error: 'Unknown error' }))) as {
110→        error?: string;
111→      };
112→      return {
113→        success: false,
114→        error: errorData.error || `Executor error: ${response.status}`,
115→        executionTimeMs,
116→      };
117→    }
118→
119→    const result = (await response.json()) as ExecuteToolResponse;
120→
121→    return {
122→      success: result.success,
123→      output: result.output,
124→      error: result.error,
125→      executionTimeMs: result.executionTimeMs || executionTimeMs,
126→    };
127→  } catch (error) {
128→    const executionTimeMs = Date.now() - startTime;
129→
130→    if (error instanceof Error && error.name === 'AbortError') {
131→      return {
132→        success: false,
133→        error: 'Execution timeout',
134→        executionTimeMs,
135→      };
136→    }
137→
138→    return {
139→      success: false,
140→      error: error instanceof Error ? error.message : String(error),
141→      executionTimeMs,
142→    };
143→  }
144→}
