146→/**
147→ * Execute a tool using the resolved executor configuration
148→ *
149→ * @param config - Resolved executor config (or null for default)
150→ * @param request - Tool execution request
151→ * @returns Execution result
152→ */
153→export async function executeWithExecutor(
154→  config: ExecutorConfig | null,
155→  request: ExecuteToolRequest
156→): Promise<ExecuteToolResponse> {
157→  const resolvedConfig = config ?? { type: 'default' };
158→
159→  // Use custom URL executor
160→  if (resolvedConfig.type === 'custom_url' && resolvedConfig.url) {
161→    return executeWithCustomUrl(resolvedConfig.url, resolvedConfig.apiKey, request);
162→  }
163→
164→  // Default: use existing package-executor (which uses SANDBOX_EXECUTOR_URL)
165→  const result = await executePackage(request.packageName, request.name, request.params, {
166→    env: request.env,
167→    version: request.version,
168→  });
169→
170→  return {
171→    success: result.success,
172→    output: result.output,
173→    error: result.error,
174→    executionTimeMs: result.executionTimeMs,
175→  };
176→}
