178→/**
179→ * Check the health of a custom executor URL
180→ *
181→ * @param url - Executor URL to check
182→ * @param apiKey - Optional API key for authentication
183→ * @returns Health check response or error
184→ */
185→export async function checkExecutorHealth(
186→  url: string,
187→  apiKey?: string
188→): Promise<{ healthy: boolean; response?: ExecutorHealthResponse; error?: string }> {
189→  const headers: Record<string, string> = {};
190→
191→  if (apiKey) {
192→    headers.Authorization = `Bearer ${apiKey}`;
193→  }
194→
195→  try {
196→    const controller = new AbortController();
197→    const timeoutId = setTimeout(() => controller.abort(), 10000); // 10 second timeout for health checks
198→
199→    const response = await fetch(`${url}/health`, {
200→      method: 'GET',
201→      headers,
202→      signal: controller.signal,
203→    });
204→
205→    clearTimeout(timeoutId);
206→
207→    if (!response.ok) {
208→      return {
209→        healthy: false,
210→        error: `Health check failed: ${response.status}`,
211→      };
212→    }
213→
214→    const data = (await response.json()) as ExecutorHealthResponse;
215→
216→    return {
217→      healthy: data.status === 'ok' || data.status === 'degraded',
218→      response: data,
219→    };
220→  } catch (error) {
221→    if (error instanceof Error && error.name === 'AbortError') {
222→      return {
223→        healthy: false,
224→        error: 'Health check timeout',
225→      };
226→    }
227→
228→    return {
229→      healthy: false,
230→      error: error instanceof Error ? error.message : 'Unknown error',
231→    };
232→  }
233→}
