  1→'use client';
  2→
  3→import { Badge } from '@tpmjs/ui/Badge/Badge';
  4→import { Button } from '@tpmjs/ui/Button/Button';
  5→import { Icon } from '@tpmjs/ui/Icon/Icon';
  6→import { Input } from '@tpmjs/ui/Input/Input';
  7→import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
  8→
  9→interface Tool {
 10→  id: string;
 11→  name: string;
 12→  description: string;
 13→  package: {
 14→    npmPackageName: string;
 15→    category: string;
 16→  };
 17→}
 18→
 19→interface AddToolSearchProps {
 20→  collectionId: string;
 21→  existingToolIds: string[];
 22→  onToolAdded: (tool: Tool) => void;
 23→}
 24→
 25→interface SearchResult {
 26→  id: string;
 27→  name: string;
 28→  description: string;
 29→  package: {
 30→    npmPackageName: string;
 31→    category: string;
 32→  };
 33→}
 34→
 35→export function AddToolSearch({
 36→  collectionId,
 37→  existingToolIds,
 38→  onToolAdded,
 39→}: AddToolSearchProps): React.ReactElement {
 40→  const [query, setQuery] = useState('');
 41→  const [results, setResults] = useState<SearchResult[]>([]);
 42→  const [isSearching, setIsSearching] = useState(false);
 43→  const [isOpen, setIsOpen] = useState(false);
 44→  const [addingId, setAddingId] = useState<string | null>(null);
 45→  const [addingPackage, setAddingPackage] = useState<string | null>(null);
 46→  const [error, setError] = useState<string | null>(null);
 47→  const searchTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
 48→  const containerRef = useRef<HTMLDivElement>(null);
 49→
 50→  // Debounced search
 51→  const search = useCallback(
 52→    async (searchQuery: string) => {
 53→      if (!searchQuery.trim()) {
 54→        setResults([]);
 55→        setIsOpen(false);
 56→        return;
 57→      }
 58→
 59→      setIsSearching(true);
 60→      setError(null);
 61→
 62→      try {
 63→        // Build URL with excludeIds to avoid returning tools already in collection
 64→        const params = new URLSearchParams({
 65→          q: searchQuery,
 66→          limit: '50', // Higher limit to handle large packages like @tpmjs/tools-unsandbox (59 tools)
 67→        });
 68→        // Pass existing tool IDs so server can exclude them
 69→        if (existingToolIds.length > 0) {
 70→          params.set('excludeIds', existingToolIds.join(','));
 71→        }
 72→        const response = await fetch(`/api/tools/search?${params.toString()}`);
 73→        const data = await response.json();
 74→
 75→        if (data.success && data.results?.tools) {
 76→          setResults(data.results.tools);
 77→          setIsOpen(true);
 78→        } else {
 79→          setResults([]);
 80→        }
 81→      } catch (err) {
 82→        console.error('Search failed:', err);
 83→        setError('Search failed');
 84→        setResults([]);
 85→      } finally {
 86→        setIsSearching(false);
 87→      }
 88→    },
 89→    [existingToolIds]
 90→  );
 91→
 92→  // Handle query changes with debounce
 93→  useEffect(() => {
 94→    if (searchTimeoutRef.current) {
 95→      clearTimeout(searchTimeoutRef.current);
 96→    }
 97→
 98→    if (query.trim()) {
 99→      searchTimeoutRef.current = setTimeout(() => {
100→        search(query);
101→      }, 300);
102→    } else {
103→      setResults([]);
104→      setIsOpen(false);
105→    }
106→
107→    return () => {
108→      if (searchTimeoutRef.current) {
109→        clearTimeout(searchTimeoutRef.current);
110→      }
111→    };
112→  }, [query, search]);
113→
114→  // Close dropdown when clicking outside
115→  useEffect(() => {
116→    const handleClickOutside = (event: MouseEvent) => {
117→      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
118→        setIsOpen(false);
119→      }
120→    };
121→
122→    document.addEventListener('mousedown', handleClickOutside);
123→    return () => document.removeEventListener('mousedown', handleClickOutside);
124→  }, []);
125→
126→  const handleAddTool = async (tool: SearchResult) => {
127→    setAddingId(tool.id);
128→    setError(null);
129→
130→    try {
131→      const response = await fetch(`/api/collections/${collectionId}/tools`, {
132→        method: 'POST',
133→        headers: { 'Content-Type': 'application/json' },
134→        body: JSON.stringify({ toolId: tool.id }),
135→      });
136→
137→      const data = await response.json();
138→
139→      if (data.success) {
140→        onToolAdded({
141→          id: tool.id,
142→          name: tool.name,
143→          description: tool.description,
144→          package: tool.package,
145→        });
146→        // Remove the added tool from results but keep dropdown open for adding more
147→        const remainingResults = results.filter((t) => t.id !== tool.id);
148→        setResults(remainingResults);
149→        // Close dropdown only if no more tools to add
150→        if (remainingResults.length === 0) {
151→          setIsOpen(false);
152→          setQuery('');
153→        }
154→      } else {
155→        setError(data.error?.message || 'Failed to add tool');
156→      }
157→    } catch (err) {
158→      console.error('Failed to add tool:', err);
159→      setError('Failed to add tool');
160→    } finally {
161→      setAddingId(null);
162→    }
163→  };
164→
165→  const handleAddPackage = async (npmPackageName: string) => {
166→    setAddingPackage(npmPackageName);
167→    setError(null);
168→
169→    try {
170→      const response = await fetch(`/api/collections/${collectionId}/tools/from-package`, {
171→        method: 'POST',
172→        headers: { 'Content-Type': 'application/json' },
173→        body: JSON.stringify({ npmPackageName }),
174→      });
175→
176→      const data = await response.json();
177→
178→      if (data.success) {
179→        // Notify parent for each added tool
180→        for (const tool of data.data.tools) {
181→          onToolAdded({
182→            id: tool.id,
183→            name: tool.name,
184→            description: tool.description,
185→            package: tool.package,
186→          });
187→        }
188→        // Remove added tools from results
189→        const addedIds = new Set(data.data.tools.map((t: { id: string }) => t.id));
190→        const remainingResults = results.filter((t) => !addedIds.has(t.id));
191→        setResults(remainingResults);
192→        if (remainingResults.length === 0) {
193→          setIsOpen(false);
194→          setQuery('');
195→        }
196→        if (data.data.limitReached) {
197→          setError(
198→            `Collection limit reached. Added ${data.data.added} of ${data.data.added + data.data.skipped} tools.`
199→          );
200→        }
201→      } else {
202→        setError(data.error?.message || 'Failed to add tools from package');
203→      }
204→    } catch (err) {
205→      console.error('Failed to add package tools:', err);
206→      setError('Failed to add tools from package');
207→    } finally {
208→      setAddingPackage(null);
209→    }
210→  };
211→
212→  // Filter out already added tools
213→  const filteredResults = results.filter((tool) => !existingToolIds.includes(tool.id));
214→
215→  // Group results by package
216→  const groupedResults = useMemo(() => {
217→    const groups: Record<string, SearchResult[]> = {};
218→    for (const tool of filteredResults) {
219→      const pkg = tool.package.npmPackageName;
220→      if (!groups[pkg]) {
221→        groups[pkg] = [];
222→      }
223→      groups[pkg].push(tool);
224→    }
225→    return groups;
226→  }, [filteredResults]);
227→
228→  const isAdding = addingId !== null || addingPackage !== null;
229→
230→  return (
231→    <div ref={containerRef} className="relative">
232→      <div className="relative">
233→        <Icon
234→          icon="search"
235→          size="sm"
236→          className="absolute left-3 top-1/2 -translate-y-1/2 text-foreground-tertiary"
237→        />
238→        <Input
239→          value={query}
240→          onChange={(e) => setQuery(e.target.value)}
241→          placeholder="Search for tools to add..."
242→          className="pl-9"
243→          onFocus={() => {
244→            if (filteredResults.length > 0) {
245→              setIsOpen(true);
246→            }
247→          }}
248→        />
249→        {isSearching && (
250→          <Icon
251→            icon="loader"
252→            size="sm"
253→            className="absolute right-3 top-1/2 -translate-y-1/2 text-foreground-tertiary animate-spin"
254→          />
255→        )}
256→      </div>
257→
258→      {error && <p className="text-sm text-error mt-2">{error}</p>}
259→
260→      {isOpen && filteredResults.length > 0 && (
261→        <div className="absolute z-50 w-full mt-2 bg-background border border-border rounded-lg shadow-lg max-h-80 overflow-y-auto">
262→          {Object.entries(groupedResults).map(([npmPackageName, tools]) => (
263→            <div key={npmPackageName}>
264→              {/* Show "Add all" header when package has 2+ tools */}
265→              {tools.length >= 2 && (
266→                <div className="flex items-center justify-between px-3 py-2 bg-surface-secondary border-b border-border">
267→                  <span className="text-xs font-medium text-foreground-secondary truncate">
268→                    {npmPackageName} ({tools.length} tools)
269→                  </span>
270→                  <Button
271→                    size="sm"
272→                    variant="secondary"
273→                    onClick={() => handleAddPackage(npmPackageName)}
274→                    loading={addingPackage === npmPackageName}
275→                    disabled={isAdding}
276→                  >
277→                    <Icon icon="plus" size="sm" className="mr-1" />
278→                    Add all {tools.length}
279→                  </Button>
280→                </div>
281→              )}
282→              {tools.map((tool) => (
283→                <div
284→                  key={tool.id}
285→                  className="p-3 hover:bg-surface-secondary transition-colors border-b border-border last:border-b-0"
286→                >
287→                  <div className="flex items-start justify-between gap-3">
288→                    <div className="flex-1 min-w-0">
289→                      <div className="flex items-center gap-2 mb-1">
290→                        <span className="font-medium text-foreground truncate">{tool.name}</span>
291→                        <Badge variant="secondary" size="sm">
292→                          {tool.package.category}
293→                        </Badge>
294→                      </div>
295→                      <p className="text-sm text-foreground-secondary line-clamp-2">
296→                        {tool.description}
297→                      </p>
298→                      {tools.length < 2 && (
299→                        <p className="text-xs text-foreground-tertiary mt-1">
300→                          {tool.package.npmPackageName}
301→                        </p>
302→                      )}
303→                    </div>
304→                    <Button
305→                      size="sm"
306→                      onClick={() => handleAddTool(tool)}
307→                      loading={addingId === tool.id}
308→                      disabled={isAdding}
309→                    >
310→                      <Icon icon="plus" size="sm" className="mr-1" />
311→                      Add
312→                    </Button>
313→                  </div>
314→                </div>
315→              ))}
316→            </div>
317→          ))}
318→        </div>
319→      )}
320→
321→      {isOpen && query.trim() && filteredResults.length === 0 && !isSearching && (
322→        <div className="absolute z-50 w-full mt-2 bg-background border border-border rounded-lg shadow-lg p-4 text-center">
323→          <p className="text-foreground-secondary">
324→            {results.length > 0
325→              ? 'All matching tools are already in this collection'
326→              : 'No tools found matching your search'}
327→          </p>
328→        </div>
329→      )}
330→    </div>
331→  );
332→}
