 10→// Get sandbox URL at runtime (not build time) for serverless environments
 11→function getSandboxUrl(): string {
 12→  const url = process.env.SANDBOX_EXECUTOR_URL || 'http://localhost:3000';
 13→  // If URL doesn't start with http:// or https://, add https://
 14→  if (!url.startsWith('http://') && !url.startsWith('https://')) {
