133→/**
134→ * POST /@username/collections/[slug]/mcp
135→ * MCP JSON-RPC endpoint (HTTP transport only)
136→ *
137→ * Authentication:
138→ * - Public collections: No auth required
139→ * - Private collections: Requires Authorization: Bearer header with valid API key
140→ */
141→export async function POST(request: NextRequest, context: RouteContext): Promise<Response> {
142→  const startTime = Date.now();
143→  let authResult: Awaited<ReturnType<typeof authenticateRequest>> | null = null;
144→
145→  try {
146→    const { username, slug } = await context.params;
147→
148→    // First, find the user by username
149→    const user = await getUserByUsername(username);
150→
151→    if (!user) {
152→      return NextResponse.json(
153→        {
154→          jsonrpc: '2.0',
155→          error: {
156→            code: -32001,
157→            message: `User '${username}' not found. Check the username in your MCP endpoint URL.`,
158→          },
159→          id: null,
160→        },
161→        { status: 404 }
162→      );
163→    }
164→
165→    // Then find the collection by user ID and slug
166→    const collection = await getCollectionByUserIdAndSlug(user.id, slug);
167→
168→    if (!collection) {
169→      return NextResponse.json(
170→        {
171→          jsonrpc: '2.0',
172→          error: {
173→            code: -32001,
174→            message: `Collection '${slug}' not found for user '${user.username}'.`,
175→          },
176→          id: null,
177→        },
178→        { status: 404 }
179→      );
180→    }
181→
182→    // Authenticate the request
183→    authResult = await authenticateRequest();
184→
185→    // Determine if the authenticated user is the owner
186→    const isOwner = authResult.authenticated && authResult.userId === collection.userId;
187→
188→    // Authorization check:
189→    // - Owners can always access their own collections (public or private)
190→    // - Non-owners can access PUBLIC collections without auth
191→    // - Private collections require auth as the owner
192→    if (!isOwner && !collection.isPublic) {
193→      // Private collection, not the owner - require authentication
194→      if (!authResult.authenticated) {
195→        return NextResponse.json(
196→          {
197→            jsonrpc: '2.0',
198→            error: {
199→              code: -32000,
200→              message: 'Authentication required. Add header: Authorization: Bearer YOUR_API_KEY',
201→            },
202→            id: null,
203→          },
204→          { status: 401 }
205→        );
206→      }
207→      // Authenticated but not the owner of a private collection - don't reveal existence
208→      return NextResponse.json(
209→        { jsonrpc: '2.0', error: { code: -32001, message: 'Collection not found' }, id: null },
210→        { status: 404 }
211→      );
212→    }
213→
214→    // Check scope if authenticated
215→    if (authResult.authenticated && !hasScope(authResult, API_KEY_SCOPES.MCP_EXECUTE)) {
216→      return NextResponse.json(
217→        {
218→          jsonrpc: '2.0',
219→          error: { code: -32000, message: 'Missing required scope: mcp:execute' },
220→          id: null,
221→        },
222→        { status: 403 }
223→      );
224→    }
225→
226→    // Rate limit if authenticated via API key
227→    if (authResult.authenticated && authResult.apiKeyId) {
228→      const rateLimitResult = await checkApiKeyRateLimit(
229→        authResult.apiKeyId,
230→        authResult.tier || 'FREE'
231→      );
232→
233→      if (!rateLimitResult.allowed) {
234→        return createRateLimitResponse(rateLimitResult);
235→      }
236→    }
237→
238→    // Parse JSON-RPC request body
239→    let body: JsonRpcRequest;
240→    try {
241→      body = await request.json();
242→    } catch {
243→      return NextResponse.json(
244→        { jsonrpc: '2.0', error: { code: -32700, message: 'Parse error' }, id: null },
245→        { status: 400 }
246→      );
247→    }
248→
249→    // Build tracking context for execution event tracking
250→    const trackingCtx: TrackingContext = {
251→      userId: authResult.authenticated ? (authResult.userId ?? undefined) : undefined,
252→      apiKeyId: authResult.authenticated ? (authResult.apiKeyId ?? undefined) : undefined,
253→      collectionId: collection.id,
254→      source: 'mcp_http',
255→    };
256→
257→    // Process the request
258→    const response = await processJsonRpcRequest(
259→      collection.id,
260→      collection.name,
261→      body,
262→      isOwner,
263→      trackingCtx
264→    );
265→    const jsonResponse = NextResponse.json(response);
266→
267→    // Track usage for authenticated requests
268→    if (authResult.authenticated && authResult.userId) {
269→      const clientMeta = await getClientMetadata();
270→      trackUsage({
271→        apiKeyId: authResult.apiKeyId,
272→        userId: authResult.userId,
273→        endpoint: `/@${user.username}/collections/${slug}/mcp`,
274→        method: 'POST',
275→        statusCode: jsonResponse.status,
276→        latencyMs: Date.now() - startTime,
277→        resourceType: 'mcp',
278→        resourceId: collection.id,
279→        userAgent: clientMeta.userAgent,
280→        ipAddress: clientMeta.ipAddress,
281→      });
282→    }
283→
284→    // Add rate limit headers for authenticated requests
285→    if (authResult.authenticated && authResult.apiKeyId) {
286→      const rateLimitResult = await checkApiKeyRateLimit(
287→        authResult.apiKeyId,
288→        authResult.tier || 'FREE'
289→      );
290→      const headers = getRateLimitHeaders(rateLimitResult);
291→      for (const [key, value] of Object.entries(headers)) {
292→        jsonResponse.headers.set(key, value);
293→      }
294→    }
295→
296→    return jsonResponse;
297→  } catch (error) {
298→    console.error('[MCP POST] Error:', error);
299→    const message = error instanceof Error ? error.message : 'Internal server error';
300→
301→    // Track error for authenticated requests
302→    if (authResult?.authenticated && authResult.userId) {
303→      const { username, slug } = await context.params;
304→      const clientMeta = await getClientMetadata();
305→      trackUsage({
306→        apiKeyId: authResult.apiKeyId,
307→        userId: authResult.userId,
308→        endpoint: `/@${username}/collections/${slug}/mcp`,
309→        method: 'POST',
310→        statusCode: 500,
311→        latencyMs: Date.now() - startTime,
312→        resourceType: 'mcp',
313→        errorCode: 'INTERNAL_ERROR',
314→        errorMessage: message,
315→        userAgent: clientMeta.userAgent,
316→        ipAddress: clientMeta.ipAddress,
317→      });
318→    }
319→
320→    return NextResponse.json(
321→      { jsonrpc: '2.0', error: { code: -32603, message }, id: null },
322→      { status: 500 }
323→    );
324→  }
