327→/**
328→ * GET /@username/collections/[slug]/mcp
329→ * Returns server info for the MCP endpoint
330→ */
331→export async function GET(_request: NextRequest, context: RouteContext): Promise<Response> {
332→  try {
333→    const { username, slug } = await context.params;
334→
335→    // First, find the user by username
336→    const user = await getUserByUsername(username);
337→
338→    if (!user) {
339→      return NextResponse.json(
340→        { error: `User '${username}' not found. Check the username in your MCP endpoint URL.` },
341→        { status: 404 }
342→      );
343→    }
344→
345→    // Then find the collection
346→    const collection = await getCollectionByUserIdAndSlug(user.id, slug);
347→
348→    if (!collection) {
349→      return NextResponse.json(
350→        { error: `Collection '${slug}' not found for user '${user.username}'.` },
351→        { status: 404 }
352→      );
353→    }
354→
355→    // For GET requests, check if user can access this collection:
356→    // - Public collections are accessible to anyone
357→    // - Private collections are only accessible to the owner (when authenticated)
358→    if (!collection.isPublic) {
359→      const authResult = await authenticateRequest();
360→      if (!authResult.authenticated || authResult.userId !== collection.userId) {
361→        // Don't reveal existence of private collections
362→        return NextResponse.json({ error: 'Collection not found' }, { status: 404 });
363→      }
364→    }
365→
366→    // Return server info
367→    return NextResponse.json({
368→      name: `TPMJS: ${collection.name}`,
369→      description: collection.description,
370→      protocol: 'mcp',
371→      transport: 'http',
372→      endpoint: `/@${user.username}/collections/${slug}/mcp`,
373→    });
374→  } catch (error) {
375→    console.error('[MCP GET] Error:', error);
376→    const message = error instanceof Error ? error.message : 'Internal server error';
377→    return NextResponse.json({ error: message }, { status: 500 });
378→  }
379→}
