 22→/**
 23→ * Fetch collection data from database
 24→ * Returns both public collections fully, and private collections with minimal info (locked state)
 25→ */
 26→async function getCollection(username: string, slug: string): Promise<CollectionResult> {
 27→  // Remove @ prefix if present
 28→  const cleanUsername = username.startsWith('@') ? username.slice(1) : username;
 29→
 30→  // First, check if the collection exists at all (public or private)
 31→  const collection = await prisma.collection.findFirst({
 32→    where: {
 33→      slug,
 34→      user: { username: cleanUsername },
 35→    },
 36→    include: {
 37→      user: {
 38→        select: {
 39→          id: true,
 40→          username: true,
 41→          name: true,
 42→          image: true,
 43→        },
 44→      },
 45→      tools: {
 46→        include: {
 47→          tool: {
 48→            include: {
 49→              package: {
 50→                select: {
 51→                  npmPackageName: true,
 52→                  category: true,
 53→                },
 54→              },
 55→            },
 56→          },
 57→        },
 58→        orderBy: { position: 'asc' },
 59→      },
 60→      forkedFrom: {
 61→        include: {
 62→          user: {
 63→            select: { username: true },
 64→          },
 65→        },
 66→      },
 67→    },
 68→  });
 69→
 70→  if (!collection) {
 71→    return { collection: null, isPrivate: false };
 72→  }
 73→
 74→  // If private, return minimal info for locked state
 75→  if (!collection.isPublic) {
 76→    return {
 77→      collection: null,
 78→      isPrivate: true,
 79→      privateName: collection.name,
 80→    };
 81→  }
 82→
 83→  // Public collection - return full data
 84→  return {
 85→    collection: {
 86→      id: collection.id,
 87→      slug: collection.slug || '',
 88→      name: collection.name,
 89→      description: collection.description,
 90→      likeCount: collection.likeCount,
 91→      toolCount: collection.tools.length,
 92→      forkCount: collection.forkCount,
 93→      createdAt: collection.createdAt.toISOString(),
 94→      createdBy: {
 95→        id: collection.user.id,
 96→        username: collection.user.username || '',
 97→        name: collection.user.name || '',
 98→        image: collection.user.image,
 99→      },
100→      tools: collection.tools.map((ct) => ({
101→        id: ct.id,
102→        toolId: ct.toolId,
103→        position: ct.position,
104→        note: ct.note,
105→        tool: {
106→          id: ct.tool.id,
107→          name: ct.tool.name,
108→          description: ct.tool.description,
109→          likeCount: ct.tool.likeCount,
110→          package: {
111→            npmPackageName: ct.tool.package.npmPackageName,
112→            category: ct.tool.package.category,
113→          },
114→        },
115→      })),
116→      forkedFromId: collection.forkedFromId,
117→      forkedFrom: collection.forkedFrom
118→        ? {
119→            id: collection.forkedFrom.id,
120→            name: collection.forkedFrom.name,
121→            slug: collection.forkedFrom.slug || '',
122→            user: {
123→              username: collection.forkedFrom.user.username || '',
124→            },
125→          }
126→        : null,
127→    },
128→    isPrivate: false,
129→  };
130→}
