  1→/**
  2→ * HLLM API Client Tools for TPMJS
  3→ * Manage topologies, sessions, prompts, files, and more.
  4→ *
  5→ * @requires HLLM_API_KEY environment variable (hllm_xxxx_xxx format)
  6→ * @requires HLLM_BASE_URL environment variable (optional, defaults to https://hllm.dev/api)
  7→ */
  8→
  9→import { jsonSchema, tool } from 'ai';
 10→
 11→const DEFAULT_BASE_URL = 'https://hllm.dev/api';
 12→
 13→/**
 14→ * Topology types supported by HLLM
 15→ */
 16→export const TOPOLOGY_TYPES = [
 17→  'single',
 18→  'sequential',
 19→  'parallel',
 20→  'map-reduce',
 21→  'scatter',
 22→  'debate',
 23→  'reflection',
 24→  'consensus',
 25→  'brainstorm',
 26→  'decomposition',
 27→  'rhetorical-triangle',
 28→  'tree-of-thoughts',
 29→  'react',
 30→  'karpathy-council',
 31→] as const;
 32→
 33→export type TopologyType = (typeof TOPOLOGY_TYPES)[number];
 34→
 35→/**
 36→ * Get API configuration from environment variables
 37→ */
 38→function getApiConfig(): { apiKey: string; baseUrl: string } {
 39→  const apiKey = process.env.HLLM_API_KEY;
 40→  const baseUrl = process.env.HLLM_BASE_URL || DEFAULT_BASE_URL;
 41→
 42→  if (!apiKey) {
 43→    throw new Error(
 44→      'HLLM_API_KEY environment variable is required. Get your API key from https://hllm.dev/settings/api-keys'
 45→    );
 46→  }
 47→
 48→  return { apiKey, baseUrl };
 49→}
 50→
 51→/**
 52→ * Make an authenticated request to the HLLM API
 53→ */
 54→async function apiRequest<T>(
 55→  method: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE',
 56→  path: string,
 57→  body?: unknown
 58→): Promise<T> {
 59→  const { apiKey, baseUrl } = getApiConfig();
 60→
 61→  const headers: Record<string, string> = {
 62→    Authorization: `Bearer ${apiKey}`,
 63→  };
 64→
 65→  if (body !== undefined) {
 66→    headers['Content-Type'] = 'application/json';
 67→  }
 68→
 69→  const response = await fetch(`${baseUrl}${path}`, {
 70→    method,
 71→    headers,
 72→    body: body !== undefined ? JSON.stringify(body) : undefined,
 73→  });
 74→
 75→  if (!response.ok) {
 76→    const errorText = await response.text().catch(() => 'Unknown error');
 77→    handleApiError(response.status, errorText);
 78→  }
 79→
 80→  return response.json() as Promise<T>;
 81→}
 82→
 83→/**
 84→ * Handle API errors with specific messages for common HTTP status codes
 85→ */
 86→function handleApiError(status: number, errorText: string): never {
 87→  switch (status) {
 88→    case 400:
 89→      throw new Error(`Bad request: ${errorText}`);
 90→    case 401:
 91→      throw new Error('Authentication failed: Invalid API key. Ensure HLLM_API_KEY is correct.');
 92→    case 403:
 93→      throw new Error(`Access forbidden: ${errorText}`);
 94→    case 404:
 95→      throw new Error(`Resource not found: ${errorText}`);
 96→    case 429:
 97→      throw new Error(`Rate limit exceeded: ${errorText}`);
 98→    case 500:
 99→    case 502:
100→    case 503:
101→      throw new Error(`HLLM service error (${status}): ${errorText}`);
102→    default:
103→      throw new Error(`HLLM API error: HTTP ${status} - ${errorText}`);
104→  }
105→}
