108→// Topology Execution
109→// ============================================================================
110→
111→export interface ExecuteTopologyInput {
112→  topologyId: TopologyType;
113→  intent: string;
114→  config?: Record<string, unknown>;
115→  sessionId?: string;
116→  conversationHistory?: Array<{
117→    role: 'user' | 'assistant' | 'system';
118→    content: string;
119→  }>;
120→}
121→
122→export interface ExecuteTopologyResult {
123→  id: string;
124→  status: string;
125→  output?: string;
126→  tokens?: {
127→    input: number;
128→    output: number;
129→    total: number;
130→  };
131→  duration?: number;
132→  steps?: Array<{
133→    id: string;
134→    role: string;
135→    content: string;
136→  }>;
137→}
138→
139→/**
140→ * Execute a topology with the given configuration.
141→ * Returns streaming SSE response with text chunks and event objects.
142→ */
143→export const executeTopology = tool({
144→  description:
145→    'Execute a topology with streaming SSE response. Supports topology types: single, sequential, parallel, map-reduce, scatter, debate, reflection, consensus, brainstorm, decomposition, rhetorical-triangle, tree-of-thoughts, react.',
146→  inputSchema: jsonSchema<ExecuteTopologyInput>({
147→    type: 'object',
148→    properties: {
149→      topologyId: {
150→        type: 'string',
151→        enum: [...TOPOLOGY_TYPES],
152→        description: 'Type of topology to execute.',
153→      },
154→      intent: {
155→        type: 'string',
156→        description: 'The task or prompt for execution (1-50,000 characters).',
157→      },
158→      config: {
159→        type: 'object',
160→        description: 'Topology-specific configuration (e.g., maxIterations for reflection).',
161→        additionalProperties: true,
162→      },
163→      sessionId: {
164→        type: 'string',
165→        description: 'Associate execution with a chat session.',
166→      },
167→      conversationHistory: {
168→        type: 'array',
169→        items: {
170→          type: 'object',
171→          properties: {
172→            role: { type: 'string', enum: ['user', 'assistant', 'system'] },
173→            content: { type: 'string' },
174→          },
175→          required: ['role', 'content'],
176→        },
177→        description: 'Previous messages for context continuity.',
178→      },
179→    },
180→    required: ['topologyId', 'intent'],
181→    additionalProperties: false,
182→  }),
183→  async execute(input: ExecuteTopologyInput): Promise<ExecuteTopologyResult> {
184→    const { apiKey, baseUrl } = getApiConfig();
185→
186→    const body: Record<string, unknown> = {
187→      topologyId: input.topologyId,
188→      intent: input.intent,
189→    };
190→
191→    if (input.config) body.config = input.config;
192→    if (input.sessionId) body.sessionId = input.sessionId;
193→    if (input.conversationHistory) body.conversationHistory = input.conversationHistory;
194→
195→    // The /api/execute endpoint returns a streaming SSE response
196→    // We need to collect the full response
197→    const response = await fetch(`${baseUrl}/execute`, {
198→      method: 'POST',
199→      headers: {
200→        Authorization: `Bearer ${apiKey}`,
201→        'Content-Type': 'application/json',
202→      },
203→      body: JSON.stringify(body),
204→    });
205→
206→    if (!response.ok) {
207→      const errorText = await response.text().catch(() => 'Unknown error');
208→      handleApiError(response.status, errorText);
209→    }
210→
211→    // Parse streaming response - collect text chunks
212→    const reader = response.body?.getReader();
213→    if (!reader) {
214→      throw new Error('No response body');
215→    }
216→
217→    const decoder = new TextDecoder();
218→    let fullText = '';
219→    let lastEvent: Record<string, unknown> | null = null;
220→
221→    while (true) {
222→      const { done, value } = await reader.read();
223→      if (done) break;
224→
225→      const chunk = decoder.decode(value, { stream: true });
226→      const lines = chunk.split('\n');
227→
228→      for (const line of lines) {
229→        if (line.startsWith('text:')) {
230→          fullText += line.slice(5);
231→        } else if (line.startsWith('event:')) {
232→          try {
233→            lastEvent = JSON.parse(line.slice(6));
234→          } catch {
235→            // Ignore parse errors
236→          }
237→        }
238→      }
239→    }
240→
241→    return {
242→      id: (lastEvent?.id as string) || 'unknown',
243→      status: 'completed',
244→      output: fullText,
245→      tokens: lastEvent?.tokens as ExecuteTopologyResult['tokens'],
246→      duration: lastEvent?.duration as number,
247→      steps: lastEvent?.steps as ExecuteTopologyResult['steps'],
248→    };
249→  },
250→});
