177→
178→    if (!session) {
179→      return NextResponse.json(
180→        {
181→          success: false,
182→          error: { code: 'UNAUTHORIZED', message: 'Authentication required' },
183→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
184→        },
185→        { status: 401 }
186→      );
187→    }
188→
189→    // Verify collection exists and user owns it
190→    const collection = await prisma.collection.findUnique({
191→      where: { id: collectionId },
192→    });
193→
194→    if (!collection) {
195→      return NextResponse.json(
196→        {
197→          success: false,
198→          error: { code: 'NOT_FOUND', message: 'Collection not found' },
199→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
200→        },
201→        { status: 404 }
202→      );
203→    }
204→
205→    if (collection.userId !== session.user.id) {
206→      return NextResponse.json(
207→        {
208→          success: false,
209→          error: { code: 'FORBIDDEN', message: 'Access denied' },
210→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
211→        },
212→        { status: 403 }
213→      );
214→    }
215→
216→    // Verify bridge tool exists in collection
217→    const bridgeTool = await prisma.collectionBridgeTool.findFirst({
218→      where: {
219→        id: bridgeToolId,
220→        collectionId,
221→      },
222→    });
223→
224→    if (!bridgeTool) {
225→      return NextResponse.json(
226→        {
227→          success: false,
228→          error: { code: 'NOT_FOUND', message: 'Bridge tool not found in collection' },
229→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
230→        },
231→        { status: 404 }
232→      );
233→    }
234→
235→    // Delete the bridge tool from collection
236→    await prisma.collectionBridgeTool.delete({
237→      where: { id: bridgeToolId },
238→    });
239→
240→    return NextResponse.json({
241→      success: true,
242→      data: {
243→        deleted: true,
244→        serverId: bridgeTool.serverId,
245→        toolName: bridgeTool.toolName,
246→      },
247→      meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
248→    });
249→  } catch (error) {
250→    console.error('[API Error] DELETE /api/collections/[id]/bridge-tools/[bridgeToolId]:', error);
251→    return NextResponse.json(
252→      {
253→        success: false,
254→        error: { code: 'INTERNAL_ERROR', message: 'Failed to remove bridge tool' },
255→        meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
256→      },
257→      { status: 500 }
258→    );
259→  }
260→}
