 14→const DB_TIMEOUT_MS = 10000; // 10 second timeout for database queries
 15→
 16→type JsonRpcId = string | number | null;
 17→
 18→interface JsonRpcResponse {
 19→  jsonrpc: '2.0';
 20→  id: JsonRpcId;
 21→  result?: unknown;
 22→  error?: { code: number; message: string; data?: unknown };
 23→}
 24→
 25→/**
 26→ * Wrap a promise with a timeout
 27→ */
 28→function withTimeout<T>(promise: Promise<T>, ms: number, errorMessage: string): Promise<T> {
 29→  return Promise.race([
 30→    promise,
 31→    new Promise<T>((_, reject) => setTimeout(() => reject(new Error(errorMessage)), ms)),
 32→  ]);
 33→}
