 35→/**
 36→ * Handle MCP initialize request
 37→ */
 38→export function handleInitialize(collectionName: string, requestId: JsonRpcId): JsonRpcResponse {
 39→  return {
 40→    jsonrpc: '2.0',
 41→    id: requestId,
 42→    result: {
 43→      protocolVersion: '2024-11-05',
 44→      serverInfo: {
 45→        name: `TPMJS: ${collectionName}`,
 46→        version: '1.0.0',
 47→      },
 48→      capabilities: { tools: {} },
 49→    },
 50→  };
 51→}
