  1→import type { MCPServerConfig } from '@tpmjs/mcp-client';
  2→import { MCPClientManager } from '@tpmjs/mcp-client';
  3→import pc from 'picocolors';
  4→
  5→interface BridgeToolCall {
  6→  callId: string;
  7→  serverId: string;
  8→  toolName: string;
  9→  args: Record<string, unknown>;
 10→}
 11→
 12→export interface BridgeOptions {
 13→  /** TPMJS API key */
 14→  apiKey: string;
 15→  /** TPMJS API URL */
 16→  apiUrl?: string;
 17→  /** MCP servers to connect to */
 18→  servers: MCPServerConfig[];
 19→  /** Poll interval in ms */
 20→  pollInterval?: number;
 21→  /** Heartbeat interval in ms */
 22→  heartbeatInterval?: number;
 23→  /** Verbose logging */
 24→  verbose?: boolean;
 25→}
 26→
 27→export class Bridge {
 28→  private mcpManager: MCPClientManager;
 29→  private options: Required<BridgeOptions>;
 30→  private isRunning = false;
 31→  private pollTimeout: ReturnType<typeof setTimeout> | null = null;
 32→  private heartbeatTimeout: ReturnType<typeof setTimeout> | null = null;
 33→
 34→  constructor(options: BridgeOptions) {
 35→    this.options = {
 36→      apiUrl: 'https://tpmjs.com',
 37→      pollInterval: 1000, // Poll every 1 second
 38→      heartbeatInterval: 30000, // Heartbeat every 30 seconds
 39→      verbose: false,
 40→      ...options,
 41→    };
 42→
 43→    this.mcpManager = new MCPClientManager({
 44→      onStatusChange: (serverId, status, error) => {
 45→        if (this.options.verbose) {
 46→          if (status === 'connected') {
 47→            this.log(`  ${pc.green('✓')} ${serverId} connected`);
 48→          } else if (status === 'error') {
 49→            this.log(`  ${pc.red('✗')} ${serverId} error: ${error}`);
 50→          }
 51→        }
 52→      },
 53→    });
 54→  }
 55→
 56→  /**
 57→   * Start the bridge
 58→   */
 59→  async start(): Promise<void> {
 60→    this.isRunning = true;
 61→
 62→    this.log(pc.bold('Starting TPMJS Bridge...\n'));
 63→
 64→    // 1. Connect to all local MCP servers
 65→    this.log('Connecting to MCP servers:');
 66→    for (const server of this.options.servers) {
 67→      try {
 68→        this.log(`  Starting ${pc.cyan(server.name)}...`);
 69→        const tools = await this.mcpManager.connect(server);
 70→        this.log(`  ${pc.green('✓')} ${server.name}: ${tools.length} tools`);
 71→        if (this.options.verbose) {
 72→          for (const tool of tools) {
 73→            this.log(`    - ${tool.name}`);
 74→          }
 75→        }
 76→      } catch (error) {
 77→        this.log(`  ${pc.red('✗')} ${server.name}: ${(error as Error).message}`);
 78→      }
 79→    }
 80→
 81→    // 2. Register with TPMJS
 82→    this.log('\nConnecting to TPMJS...');
 83→    await this.registerTools();
 84→
 85→    // 3. Start polling for tool calls
 86→    this.startPolling();
 87→    this.startHeartbeat();
 88→  }
 89→
 90→  /**
 91→   * Stop the bridge
 92→   */
 93→  async stop(): Promise<void> {
 94→    this.isRunning = false;
 95→
 96→    this.log('\nShutting down...');
 97→
 98→    // Clear timers
 99→    if (this.pollTimeout) {
100→      clearTimeout(this.pollTimeout);
101→      this.pollTimeout = null;
102→    }
103→    if (this.heartbeatTimeout) {
104→      clearTimeout(this.heartbeatTimeout);
105→      this.heartbeatTimeout = null;
106→    }
107→
108→    // Notify TPMJS we're disconnecting
109→    try {
110→      await fetch(`${this.options.apiUrl}/api/bridge`, {
111→        method: 'DELETE',
112→        headers: {
113→          Authorization: `Bearer ${this.options.apiKey}`,
114→        },
115→      });
116→    } catch {
117→      // Ignore disconnect errors
118→    }
119→
120→    // Disconnect all MCP servers
121→    await this.mcpManager.disconnectAll();
122→
123→    this.log('Bridge stopped');
124→  }
125→
126→  private async registerTools(): Promise<void> {
127→    const allTools = this.mcpManager.listAllTools();
128→
129→    const response = await fetch(`${this.options.apiUrl}/api/bridge`, {
130→      method: 'POST',
131→      headers: {
132→        'Content-Type': 'application/json',
133→        Authorization: `Bearer ${this.options.apiKey}`,
134→      },
135→      body: JSON.stringify({
136→        type: 'register',
137→        tools: allTools.map(({ serverId, serverName, tool }) => ({
138→          serverId,
139→          serverName,
140→          name: tool.name,
141→          description: tool.description,
142→          inputSchema: tool.inputSchema,
143→        })),
144→        clientVersion: '0.1.0',
145→        clientOS: process.platform,
146→      }),
147→    });
148→
149→    if (!response.ok) {
150→      const error = await response.text();
151→      throw new Error(`Failed to register: ${error}`);
152→    }
153→
154→    this.log(`${pc.green('✓')} Connected to TPMJS`);
155→    this.log(`Registered ${allTools.length} tools`);
156→  }
157→
158→  private startPolling(): void {
159→    const poll = async () => {
160→      if (!this.isRunning) return;
161→
162→      try {
163→        const response = await fetch(`${this.options.apiUrl}/api/bridge`, {
164→          method: 'GET',
165→          headers: {
166→            Authorization: `Bearer ${this.options.apiKey}`,
167→          },
168→        });
169→
170→        if (response.ok) {
171→          const data = (await response.json()) as { calls?: BridgeToolCall[] };
172→          const calls = data.calls || [];
173→
174→          // Process each tool call
175→          for (const call of calls) {
176→            await this.handleToolCall(call);
177→          }
178→        }
179→      } catch (error) {
180→        if (this.options.verbose) {
181→          this.log(`${pc.yellow('!')} Poll error: ${(error as Error).message}`);
182→        }
183→      }
184→
185→      // Schedule next poll
186→      if (this.isRunning) {
187→        this.pollTimeout = setTimeout(poll, this.options.pollInterval);
188→      }
189→    };
190→
191→    poll();
192→  }
193→
194→  private startHeartbeat(): void {
195→    const heartbeat = async () => {
196→      if (!this.isRunning) return;
197→
198→      try {
199→        await fetch(`${this.options.apiUrl}/api/bridge`, {
200→          method: 'POST',
201→          headers: {
202→            'Content-Type': 'application/json',
203→            Authorization: `Bearer ${this.options.apiKey}`,
204→          },
205→          body: JSON.stringify({ type: 'heartbeat' }),
206→        });
207→      } catch {
