219→  private async handleToolCall(call: BridgeToolCall): Promise<void> {
220→    const { callId, serverId, toolName, args } = call;
221→
222→    if (this.options.verbose) {
223→      this.log(`Tool call: ${serverId}/${toolName}`);
224→    }
225→
226→    try {
227→      const result = await this.mcpManager.callTool(serverId, toolName, args);
228→
229→      await fetch(`${this.options.apiUrl}/api/bridge`, {
230→        method: 'POST',
231→        headers: {
232→          'Content-Type': 'application/json',
233→          Authorization: `Bearer ${this.options.apiKey}`,
234→        },
235→        body: JSON.stringify({
236→          type: 'tool_result',
237→          callId,
238→          result: {
239→            content: result.content,
240→            isError: result.isError,
241→          },
242→        }),
243→      });
244→
245→      if (this.options.verbose) {
246→        this.log(`  ${pc.green('✓')} Result sent`);
247→      }
248→    } catch (error) {
249→      await fetch(`${this.options.apiUrl}/api/bridge`, {
250→        method: 'POST',
251→        headers: {
252→          'Content-Type': 'application/json',
253→          Authorization: `Bearer ${this.options.apiKey}`,
254→        },
255→        body: JSON.stringify({
256→          type: 'tool_result',
257→          callId,
258→          error: {
259→            code: 'EXECUTION_FAILED',
260→            message: (error as Error).message,
261→          },
262→        }),
263→      });
264→
265→      if (this.options.verbose) {
266→        this.log(`  ${pc.red('✗')} Error: ${(error as Error).message}`);
267→      }
268→    }
269→  }
