 42→function withTimeout<T>(promise: Promise<T>, ms: number, errorMessage: string): Promise<T> {
 43→  return Promise.race([
 44→    promise,
 45→    new Promise<T>((_, reject) => setTimeout(() => reject(new Error(errorMessage)), ms)),
 46→  ]);
 47→}
