339→/**
340→ * Handle a bridge tool call by routing it through the user's bridge connection
341→ */
342→async function handleBridgeToolCall(
343→  collectionId: string,
344→  serverId: string,
345→  toolName: string,
346→  args: Record<string, unknown>,
347→  requestId: JsonRpcId
348→): Promise<JsonRpcResponse> {
349→  try {
350→    // Get the collection's owner and their bridge connection
351→    const collection = await withTimeout(
352→      prisma.collection.findUnique({
353→        where: { id: collectionId },
354→        include: {
355→          bridgeTools: {
356→            where: { serverId, toolName },
357→          },
358→          user: {
359→            include: { bridgeConnection: true },
360→          },
361→        },
362→      }),
363→      DB_TIMEOUT_MS,
364→      'Database query timed out'
365→    );
366→
367→    if (!collection) {
368→      return {
369→        jsonrpc: '2.0',
370→        id: requestId,
371→        error: { code: -32602, message: 'Collection not found' },
372→      };
373→    }
374→
375→    // Verify the bridge tool exists in the collection
376→    const bridgeTool = collection.bridgeTools[0];
377→    if (!bridgeTool) {
378→      return {
379→        jsonrpc: '2.0',
380→        id: requestId,
381→        error: {
382→          code: -32602,
383→          message: `Bridge tool not found in collection: ${serverId}/${toolName}`,
384→        },
385→      };
386→    }
387→
388→    // Verify the user has an active bridge connection
389→    const bridgeConnection = collection.user.bridgeConnection;
390→    if (!bridgeConnection || bridgeConnection.status !== 'connected') {
391→      return {
392→        jsonrpc: '2.0',
393→        id: requestId,
394→        result: {
395→          content: [
396→            {
397→              type: 'text',
398→              text: 'Error: Bridge is not connected. Start the bridge CLI to use bridge tools.',
399→            },
400→          ],
401→          isError: true,
402→        },
403→      };
404→    }
405→
406→    // Check if the bridge is stale (not seen in 2 minutes)
407→    if (bridgeConnection.lastSeen) {
408→      const staleThreshold = 2 * 60 * 1000; // 2 minutes
409→      if (Date.now() - bridgeConnection.lastSeen.getTime() > staleThreshold) {
410→        return {
411→          jsonrpc: '2.0',
412→          id: requestId,
413→          result: {
414→            content: [
415→              {
416→                type: 'text',
417→                text: 'Error: Bridge connection appears stale. Please check if the bridge CLI is running.',
418→              },
419→            ],
420→            isError: true,
421→          },
422→        };
423→      }
424→    }
425→
426→    // Generate a unique call ID
427→    const callId = `${Date.now()}-${Math.random().toString(36).slice(2, 11)}`;
428→
429→    // Queue the tool call for the bridge to pick up
430→    queueBridgeToolCall(collection.user.id, callId, serverId, toolName, args);
431→
432→    // Wait for the result (with 5 minute timeout)
433→    const result = await waitForBridgeResult(callId, 300000);
434→
435→    if (result.error) {
436→      return {
437→        jsonrpc: '2.0',
438→        id: requestId,
439→        result: {
440→          content: [{ type: 'text', text: `Error: ${result.error.message}` }],
441→          isError: true,
442→        },
443→      };
444→    }
445→
446→    // Format the result
447→    const content = result.result as { content?: unknown[]; isError?: boolean } | undefined;
448→    if (content?.content) {
449→      return {
450→        jsonrpc: '2.0',
451→        id: requestId,
452→        result: {
453→          content: content.content,
454→          isError: content.isError,
455→        },
456→      };
457→    }
458→
459→    return {
460→      jsonrpc: '2.0',
461→      id: requestId,
462→      result: {
463→        content: [
464→          {
465→            type: 'text',
466→            text:
467→              typeof result.result === 'string'
468→                ? result.result
469→                : JSON.stringify(result.result, null, 2),
470→          },
471→        ],
472→      },
473→    };
474→  } catch (error) {
475→    console.error('[MCP bridge tool call] Error:', error);
476→    return {
477→      jsonrpc: '2.0',
478→      id: requestId,
479→      error: { code: -32603, message: error instanceof Error ? error.message : 'Internal error' },
480→    };
481→  }
482→}
