 94→type TabId = 'tools' | 'connect' | 'env-vars' | 'settings';
 95→
 96→const VALID_TABS: TabId[] = ['tools', 'connect', 'env-vars', 'settings'];
 97→
 98→export default function CollectionDetailPage(): React.ReactElement {
 99→  const params = useParams();
100→  const router = useRouter();
101→  const searchParams = useSearchParams();
102→  const collectionId = params.id as string;
103→
104→  // Get initial tab from URL or default to 'tools'
105→  const tabFromUrl = searchParams.get('tab') as TabId | null;
106→  const initialTab = tabFromUrl && VALID_TABS.includes(tabFromUrl) ? tabFromUrl : 'tools';
107→
108→  const [collection, setCollection] = useState<Collection | null>(null);
109→  const [isLoading, setIsLoading] = useState(true);
110→  const [error, setError] = useState<string | null>(null);
111→  const [activeTab, setActiveTab] = useState<TabId>(initialTab);
112→  const [isUpdating, setIsUpdating] = useState(false);
113→  const [removingToolId, setRemovingToolId] = useState<string | null>(null);
114→  const [isDeleting, setIsDeleting] = useState(false);
115→  const [executorConfig, setExecutorConfig] = useState<ExecutorConfig | null>(null);
116→  const [envVars, setEnvVars] = useState<Record<string, string> | null>(null);
117→  const [showClaudeConfig, setShowClaudeConfig] = useState(false);
118→
119→  // Update URL when tab changes
120→  const handleTabChange = (tabId: string) => {
121→    const newTab = tabId as TabId;
122→    setActiveTab(newTab);
123→    const newParams = new URLSearchParams(searchParams.toString());
124→    if (newTab === 'tools') {
125→      newParams.delete('tab');
126→    } else {
127→      newParams.set('tab', newTab);
128→    }
129→    const queryString = newParams.toString();
130→    router.replace(
131→      `/dashboard/collections/${collectionId}${queryString ? `?${queryString}` : ''}`,
132→      {
133→        scroll: false,
134→      }
135→    );
136→  };
137→
138→  const fetchCollection = useCallback(async () => {
139→    try {
140→      const response = await fetch(`/api/collections/${collectionId}`);
141→      const data = await response.json();
142→
143→      if (data.success) {
144→        setCollection(data.data);
145→        if (data.data.executorType === 'custom_url' && data.data.executorConfig) {
146→          setExecutorConfig({
147→            type: 'custom_url',
148→            url: data.data.executorConfig.url,
149→            apiKey: data.data.executorConfig.apiKey,
150→          });
151→        } else {
152→          setExecutorConfig(data.data.executorType ? { type: 'default' } : null);
153→        }
154→        if (data.data.envVars && typeof data.data.envVars === 'object') {
155→          setEnvVars(data.data.envVars as Record<string, string>);
156→        } else {
157→          setEnvVars(null);
158→        }
159→      } else {
160→        if (data.error?.code === 'UNAUTHORIZED') {
161→          router.push('/sign-in');
162→          return;
163→        }
164→        if (data.error?.code === 'NOT_FOUND') {
165→          router.push('/dashboard/collections');
166→          return;
