 10→
 11→interface EnvVar {
 12→  name: string;
 13→  description?: string;
 14→}
 15→
 16→interface InstallationSectionProps {
 17→  collection: {
 18→    id: string;
 19→    slug: string;
 20→    name: string;
 21→    toolCount: number;
 22→    envVars?: Record<string, string> | null;
 23→  };
 24→  username: string;
 25→  isPrivate: boolean;
 26→  /** Whether to show the fork button (typically false for dashboard/owner view) */
 27→  showForkButton?: boolean;
 28→}
 29→
 30→export function InstallationSection({
 31→  collection,
 32→  username,
 33→  isPrivate,
 34→  showForkButton = true,
 35→}: InstallationSectionProps) {
 36→  const [copiedCommand, setCopiedCommand] = useState(false);
 37→  const [showClaudeDesktop, setShowClaudeDesktop] = useState(false);
 38→  const [showTroubleshooting, setShowTroubleshooting] = useState(false);
 39→
 40→  const baseUrl = typeof window !== 'undefined' ? window.location.origin : 'https://tpmjs.com';
 41→  const mcpUrl = `${baseUrl}/@${username}/collections/${collection.slug}/mcp`;
 42→
 43→  // Build the claude mcp add command
 44→  // Positional args (name, url) must come before flags to avoid -H swallowing them
 45→  const commandParts = ['claude mcp add'];
 46→  commandParts.push(collection.slug);
 47→  commandParts.push(mcpUrl);
 48→  commandParts.push('-t http');
 49→  if (isPrivate) {
 50→    commandParts.push('-H "Authorization: Bearer YOUR_TPMJS_API_KEY"');
 51→  }
 52→
 53→  const installCommand = commandParts.join(' \\\n  ');
 54→
 55→  // Build Claude Desktop config JSON
 56→  const claudeDesktopConfig = isPrivate
