 13→interface ApiResponse<T = unknown> {
 14→  success: boolean;
 15→  data?: T;
 16→  error?: {
 17→    code: string;
 18→    message: string;
 19→    details?: Record<string, unknown>;
 20→  };
 21→  meta: {
 22→    version: string;
