151→/**
152→ * POST /api/collections/[id]/bridge-tools
153→ * Add a bridge tool to a collection
154→ */
155→export async function POST(
156→  request: NextRequest,
157→  context: RouteContext
158→): Promise<NextResponse<ApiResponse>> {
159→  const requestId = crypto.randomUUID();
160→  const { id: collectionId } = await context.params;
161→
162→  try {
163→    // Check authentication
164→    const session = await auth.api.getSession({
165→      headers: await headers(),
166→    });
167→
168→    if (!session) {
169→      return NextResponse.json(
170→        {
171→          success: false,
172→          error: { code: 'UNAUTHORIZED', message: 'Authentication required' },
173→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
174→        },
175→        { status: 401 }
176→      );
177→    }
178→
179→    // Verify collection exists and user owns it
180→    const collection = await prisma.collection.findUnique({
181→      where: { id: collectionId },
182→      include: {
183→        _count: { select: { bridgeTools: true } },
184→        user: {
185→          include: {
186→            bridgeConnection: true,
187→          },
188→        },
189→      },
190→    });
191→
192→    if (!collection) {
193→      return NextResponse.json(
194→        {
195→          success: false,
196→          error: { code: 'NOT_FOUND', message: 'Collection not found' },
197→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
198→        },
199→        { status: 404 }
200→      );
201→    }
202→
203→    if (collection.userId !== session.user.id) {
204→      return NextResponse.json(
205→        {
206→          success: false,
207→          error: { code: 'FORBIDDEN', message: 'Access denied' },
208→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
209→        },
210→        { status: 403 }
211→      );
212→    }
213→
214→    // Parse and validate request body
215→    const body = await request.json();
216→    const parseResult = AddBridgeToolToCollectionSchema.safeParse(body);
217→
218→    if (!parseResult.success) {
219→      return NextResponse.json(
220→        {
221→          success: false,
222→          error: {
223→            code: 'VALIDATION_ERROR',
224→            message: 'Invalid request body',
225→            details: { errors: parseResult.error.flatten().fieldErrors },
226→          },
227→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
228→        },
229→        { status: 400 }
230→      );
231→    }
232→
233→    const { serverId, toolName, displayName, note } = parseResult.data;
234→
235→    // Check bridge tool limit
236→    if (collection._count.bridgeTools >= COLLECTION_LIMITS.MAX_BRIDGE_TOOLS_PER_COLLECTION) {
237→      return NextResponse.json(
238→        {
239→          success: false,
240→          error: {
241→            code: 'LIMIT_EXCEEDED',
242→            message: `Maximum ${COLLECTION_LIMITS.MAX_BRIDGE_TOOLS_PER_COLLECTION} bridge tools per collection`,
243→          },
244→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
245→        },
246→        { status: 400 }
247→      );
248→    }
249→
250→    // Check if the user has a bridge connection with this tool
251→    const bridgeConnection = collection.user.bridgeConnection;
252→    if (!bridgeConnection) {
253→      return NextResponse.json(
254→        {
255→          success: false,
256→          error: {
257→            code: 'NO_BRIDGE',
258→            message: 'No bridge connection found. Please start the bridge CLI first.',
259→          },
260→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
261→        },
262→        { status: 400 }
263→      );
264→    }
265→
266→    interface BridgeTool {
267→      serverId: string;
268→      serverName: string;
269→      name: string;
270→      description?: string;
271→    }
272→
273→    const availableTools = (bridgeConnection.tools as unknown as BridgeTool[]) || [];
274→    const bridgeTool = availableTools.find((t) => t.serverId === serverId && t.name === toolName);
275→
276→    if (!bridgeTool) {
277→      return NextResponse.json(
278→        {
279→          success: false,
280→          error: {
281→            code: 'TOOL_NOT_FOUND',
282→            message: `Tool ${toolName} from server ${serverId} not found in your bridge connection`,
283→          },
284→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
285→        },
286→        { status: 404 }
287→      );
288→    }
289→
290→    // Check if tool is already in collection
291→    const existingEntry = await prisma.collectionBridgeTool.findUnique({
292→      where: {
293→        collectionId_serverId_toolName: {
294→          collectionId,
295→          serverId,
296→          toolName,
297→        },
298→      },
299→    });
300→
301→    if (existingEntry) {
302→      return NextResponse.json(
303→        {
304→          success: false,
305→          error: {
306→            code: 'DUPLICATE_TOOL',
307→            message: 'This bridge tool is already in the collection',
308→          },
309→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
310→        },
311→        { status: 409 }
312→      );
313→    }
314→
315→    // Add bridge tool to collection
316→    const collectionBridgeTool = await prisma.collectionBridgeTool.create({
317→      data: {
318→        collectionId,
319→        serverId,
320→        toolName,
321→        displayName: displayName || null,
322→        note: note || null,
323→      },
324→    });
325→
326→    return NextResponse.json(
327→      {
328→        success: true,
329→        data: {
330→          id: collectionBridgeTool.id,
331→          serverId: collectionBridgeTool.serverId,
332→          toolName: collectionBridgeTool.toolName,
333→          displayName: collectionBridgeTool.displayName,
334→          note: collectionBridgeTool.note,
335→          createdAt: collectionBridgeTool.createdAt,
336→          serverName: bridgeTool.serverName,
337→          description: bridgeTool.description,
338→        },
339→        meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
340→      },
341→      { status: 201 }
342→    );
343→  } catch (error) {
344→    console.error('[API Error] POST /api/collections/[id]/bridge-tools:', error);
345→    return NextResponse.json(
346→      {
347→        success: false,
348→        error: { code: 'INTERNAL_ERROR', message: 'Failed to add bridge tool' },
349→        meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
350→      },
351→      { status: 500 }
352→    );
353→  }
354→}
