136→/**
137→ * Handle MCP tools/call request
138→ * @param callerEnvVars - Optional env vars from caller (non-owner accessing public collection)
139→ *                        When provided, these are used INSTEAD of collection's stored env vars
140→ * @param trackingCtx - Optional tracking context for execution event tracking
141→ * @param headerEnvVars - Optional env vars extracted from request headers (e.g. tpmjs-api-key → TPMJS_API_KEY)
142→ */
143→export async function handleToolsCall(
144→  collectionId: string,
145→  params: ToolsCallParams,
146→  requestId: JsonRpcId,
147→  callerEnvVars?: Record<string, string>,
148→  trackingCtx?: TrackingContext,
149→  headerEnvVars?: Record<string, string>
150→): Promise<JsonRpcResponse> {
151→  try {
152→    const parsed = parseToolName(params.name);
153→    if (!parsed) {
154→      return {
155→        jsonrpc: '2.0',
156→        id: requestId,
157→        error: { code: -32602, message: `Invalid tool name: ${params.name}` },
158→      };
159→    }
160→
161→    // Handle bridge tool calls
162→    if (parsed.type === 'bridge') {
163→      return handleBridgeToolCall(
164→        collectionId,
165→        parsed.serverId,
166→        parsed.toolName,
167→        params.arguments ?? {},
168→        requestId
169→      );
170→    }
171→
172→    // Handle registry tool calls
173→    // Verify tool exists in collection and get executor config
174→    const collection = await withTimeout(
175→      prisma.collection.findUnique({
176→        where: { id: collectionId },
177→        select: {
178→          executorType: true,
179→          executorConfig: true,
180→          envVars: true,
181→          tools: {
182→            include: { tool: { include: { package: true } } },
183→          },
184→        },
185→      }),
186→      DB_TIMEOUT_MS,
187→      'Database query timed out'
188→    );
189→
190→    // Try all possible package name and tool name combinations
191→    // This handles both old format (full package name) and new shortened format
192→    type CollectionTool = NonNullable<typeof collection>['tools'][number];
193→    let collectionTool: CollectionTool | undefined;
194→
195→    for (const pkgName of parsed.possiblePackages) {
196→      for (const toolName of parsed.possibleToolNames) {
197→        collectionTool = collection?.tools.find(
198→          (ct) => ct.tool.package.npmPackageName === pkgName && ct.tool.name === toolName
199→        );
200→        if (collectionTool) break;
201→      }
202→      if (collectionTool) break;
203→    }
204→
205→    if (!collectionTool) {
206→      return {
207→        jsonrpc: '2.0',
208→        id: requestId,
209→        error: { code: -32602, message: `Tool not found in collection: ${params.name}` },
210→      };
211→    }
212→
213→    // Get the actual package name and version that matched
214→    const actualPackageName = collectionTool.tool.package.npmPackageName;
215→    const actualVersion = collectionTool.tool.package.npmVersion;
216→
217→    // When caller provides env vars (non-owner), validate required env vars
218→    if (callerEnvVars !== undefined) {
219→      const packageEnv = collectionTool.tool.package.env as TpmjsEnv[] | null;
220→      if (packageEnv && Array.isArray(packageEnv)) {
221→        const missingVars = packageEnv.filter(
222→          (env) => env.required !== false && !env.default && !callerEnvVars[env.name]
223→        );
224→
225→        if (missingVars.length > 0) {
226→          return {
227→            jsonrpc: '2.0',
228→            id: requestId,
229→            error: {
230→              code: -32602,
231→              message: 'Missing required environment variables',
232→              data: {
233→                missingVars: missingVars.map((e) => ({
234→                  name: e.name,
235→                  description: e.description,
236→                })),
237→              },
238→            },
239→          };
240→        }
241→      }
242→    }
243→
244→    // Resolve executor configuration (collection config only for MCP - no agent context)
245→    const executorConfig = parseExecutorConfig(
246→      collection?.executorType,
247→      collection?.executorConfig
248→    );
249→
250→    // Execute via resolved executor
251→    // Use caller-provided env vars if given (non-owner), otherwise use collection's stored env vars
252→    // Merge in any env vars extracted from request headers (e.g. tpmjs-api-key → TPMJS_API_KEY)
253→    const effectiveEnvVars = {
254→      ...(callerEnvVars ?? (collection?.envVars as Record<string, string>) ?? {}),
255→      ...headerEnvVars,
256→    };
257→    // Pass explicit version to avoid Deno HTTP import cache issues with @latest
258→    // Use actual tool name from DB, not parsed name (which may have wrong suffix)
259→    const execStart = Date.now();
260→    const result = await executeWithExecutor(executorConfig, {
261→      packageName: actualPackageName,
262→      name: collectionTool.tool.name,
263→      version: actualVersion,
264→      params: params.arguments ?? {},
265→      env: Object.keys(effectiveEnvVars).length > 0 ? effectiveEnvVars : undefined,
266→    });
267→    const execDurationMs = Date.now() - execStart;
268→
269→    // Track execution event (fire-and-forget)
270→    if (trackingCtx) {
271→      trackExecution({
272→        eventType: 'tool_call',
273→        source: trackingCtx.source,
274→        userId: trackingCtx.userId,
275→        apiKeyId: trackingCtx.apiKeyId,
276→        toolId: collectionTool.tool.id,
277→        collectionId: trackingCtx.collectionId ?? collectionId,
278→        toolName: collectionTool.tool.name,
279→        packageName: actualPackageName,
280→        status: result.success ? 'success' : 'error',
281→        durationMs: execDurationMs,
282→        errorMessage: result.success ? undefined : String(result.error),
283→      });
284→
285→      // Log user-facing activity (fire-and-forget)
286→      if (trackingCtx.userId) {
287→        logActivity({
288→          userId: trackingCtx.userId,
289→          type: 'TOOL_EXECUTED',
290→          targetName: collectionTool.tool.name,
291→          targetType: 'tool',
292→          toolId: collectionTool.tool.id,
293→          collectionId: trackingCtx.collectionId ?? collectionId,
294→          metadata: {
295→            source: trackingCtx.source,
296→            status: result.success ? 'success' : 'error',
297→            packageName: actualPackageName,
298→          },
299→        });
300→      }
301→    }
302→
303→    if (!result.success) {
304→      return {
305→        jsonrpc: '2.0',
306→        id: requestId,
307→        result: {
308→          content: [{ type: 'text', text: `Error: ${result.error}` }],
309→          isError: true,
310→        },
311→      };
312→    }
313→
314→    return {
315→      jsonrpc: '2.0',
316→      id: requestId,
317→      result: {
318→        content: [
319→          {
320→            type: 'text',
321→            text:
322→              typeof result.output === 'string'
323→                ? result.output
324→                : JSON.stringify(result.output, null, 2),
325→          },
326→        ],
327→      },
328→    };
329→  } catch (error) {
330→    console.error('[MCP tools/call] Error:', error);
331→    return {
332→      jsonrpc: '2.0',
333→      id: requestId,
334→      error: { code: -32603, message: error instanceof Error ? error.message : 'Internal error' },
335→    };
336→  }
337→}
