  1→import { Client } from '@modelcontextprotocol/sdk/client/index.js';
  2→import { StdioClientTransport } from '@modelcontextprotocol/sdk/client/stdio.js';
  3→import type {
  4→  ConnectedServer,
  5→  MCPClientStatus,
  6→  MCPServerConfig,
  7→  MCPTool,
  8→  MCPToolResult,
  9→} from './types.js';
 10→
 11→interface ManagedClient {
 12→  config: MCPServerConfig;
 13→  client: Client;
 14→  transport: StdioClientTransport;
 15→  status: MCPClientStatus;
 16→  tools: MCPTool[];
 17→  error?: string;
 18→}
 19→
 20→/**
 21→ * Manages connections to multiple MCP servers
 22→ */
 23→export class MCPClientManager {
 24→  private clients: Map<string, ManagedClient> = new Map();
 25→  private onStatusChange?: (serverId: string, status: MCPClientStatus, error?: string) => void;
 26→
 27→  constructor(options?: {
 28→    onStatusChange?: (serverId: string, status: MCPClientStatus, error?: string) => void;
 29→  }) {
 30→    this.onStatusChange = options?.onStatusChange;
 31→  }
 32→
 33→  /**
 34→   * Connect to an MCP server
 35→   */
 36→  async connect(config: MCPServerConfig): Promise<MCPTool[]> {
 37→    // Disconnect existing connection if any
 38→    if (this.clients.has(config.id)) {
 39→      await this.disconnect(config.id);
 40→    }
 41→
 42→    this.updateStatus(config.id, 'connecting');
 43→
 44→    try {
 45→      const client = new Client({
 46→        name: 'tpmjs-bridge',
 47→        version: '1.0.0',
 48→      });
 49→
 50→      const transport = new StdioClientTransport({
 51→        command: config.command,
 52→        args: config.args || [],
 53→        env: config.env,
 54→      });
 55→
 56→      await client.connect(transport);
 57→
 58→      // Discover tools
 59→      const toolsResult = await client.listTools();
 60→      const tools: MCPTool[] = toolsResult.tools.map((tool) => ({
 61→        name: tool.name,
 62→        description: tool.description,
 63→        inputSchema: tool.inputSchema as MCPTool['inputSchema'],
 64→      }));
 65→
 66→      this.clients.set(config.id, {
 67→        config,
 68→        client,
 69→        transport,
 70→        status: 'connected',
 71→        tools,
 72→      });
 73→
 74→      this.updateStatus(config.id, 'connected');
 75→      return tools;
 76→    } catch (error) {
 77→      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
 78→      this.updateStatus(config.id, 'error', errorMessage);
 79→      throw error;
 80→    }
 81→  }
 82→
 83→  /**
 84→   * Disconnect from an MCP server
 85→   */
 86→  async disconnect(serverId: string): Promise<void> {
 87→    const managed = this.clients.get(serverId);
 88→    if (!managed) return;
 89→
 90→    try {
 91→      await managed.client.close();
 92→    } catch {
 93→      // Ignore close errors
 94→    }
 95→
 96→    this.clients.delete(serverId);
 97→    this.updateStatus(serverId, 'disconnected');
 98→  }
 99→
100→  /**
101→   * Disconnect from all servers
102→   */
103→  async disconnectAll(): Promise<void> {
104→    const ids = Array.from(this.clients.keys());
105→    await Promise.all(ids.map((id) => this.disconnect(id)));
106→  }
107→
108→  /**
109→   * List tools from a specific server
110→   */
111→  listTools(serverId: string): MCPTool[] {
112→    const managed = this.clients.get(serverId);
113→    if (!managed) {
114→      throw new Error(`Server ${serverId} not connected`);
115→    }
116→    return managed.tools;
117→  }
118→
119→  /**
120→   * List all tools from all connected servers
121→   */
122→  listAllTools(): Array<{ serverId: string; serverName: string; tool: MCPTool }> {
123→    const allTools: Array<{ serverId: string; serverName: string; tool: MCPTool }> = [];
124→
125→    for (const [serverId, managed] of this.clients) {
126→      if (managed.status === 'connected') {
127→        for (const tool of managed.tools) {
128→          allTools.push({
129→            serverId,
130→            serverName: managed.config.name,
131→            tool,
132→          });
133→        }
134→      }
135→    }
136→
137→    return allTools;
138→  }
139→
140→  /**
141→   * Call a tool on a specific server
142→   */
143→  async callTool(
144→    serverId: string,
145→    toolName: string,
146→    args: Record<string, unknown>
147→  ): Promise<MCPToolResult> {
148→    const managed = this.clients.get(serverId);
149→    if (!managed) {
150→      throw new Error(`Server ${serverId} not connected`);
151→    }
152→
153→    if (managed.status !== 'connected') {
154→      throw new Error(`Server ${serverId} is not connected (status: ${managed.status})`);
155→    }
156→
157→    const result = await managed.client.callTool({
158→      name: toolName,
159→      arguments: args,
160→    });
161→
162→    return {
163→      content: result.content as MCPToolResult['content'],
164→      isError: result.isError === true,
165→    };
166→  }
167→
168→  /**
169→   * Get status of all servers
170→   */
171→  getServers(): ConnectedServer[] {
172→    return Array.from(this.clients.values()).map((managed) => ({
173→      id: managed.config.id,
174→      name: managed.config.name,
175→      status: managed.status,
176→      tools: managed.tools,
177→      error: managed.error,
178→    }));
179→  }
180→
181→  /**
182→   * Get status of a specific server
183→   */
184→  getServer(serverId: string): ConnectedServer | undefined {
185→    const managed = this.clients.get(serverId);
186→    if (!managed) return undefined;
187→
188→    return {
189→      id: managed.config.id,
190→      name: managed.config.name,
191→      status: managed.status,
192→      tools: managed.tools,
193→      error: managed.error,
194→    };
195→  }
196→
197→  /**
198→   * Check if a server is connected
199→   */
200→  isConnected(serverId: string): boolean {
201→    const managed = this.clients.get(serverId);
202→    return managed?.status === 'connected';
203→  }
204→
205→  private updateStatus(serverId: string, status: MCPClientStatus, error?: string): void {
206→    const managed = this.clients.get(serverId);
207→    if (managed) {
208→      managed.status = status;
209→      managed.error = error;
210→    }
211→    this.onStatusChange?.(serverId, status, error);
212→  }
213→}
