 1→/**
 2→ * Configuration for an MCP server connection
 3→ */
 4→export interface MCPServerConfig {
 5→  /** Unique identifier for this server */
 6→  id: string;
 7→  /** Display name for the server */
 8→  name: string;
 9→  /** Transport type */
10→  transport: 'stdio';
11→  /** Command to run the MCP server */
12→  command: string;
13→  /** Arguments to pass to the command */
14→  args?: string[];
15→  /** Environment variables to set */
16→  env?: Record<string, string>;
17→}
18→
19→/**
20→ * MCP tool definition
21→ */
22→export interface MCPTool {
23→  /** Tool name */
24→  name: string;
25→  /** Tool description */
26→  description?: string;
27→  /** JSON Schema for input parameters */
28→  inputSchema: {
29→    type: 'object';
30→    properties?: Record<string, unknown>;
31→    required?: string[];
32→    [key: string]: unknown;
33→  };
34→}
35→
36→/**
37→ * Result from an MCP tool call
38→ */
39→export interface MCPToolResult {
40→  content: Array<{
41→    type: 'text' | 'image' | 'resource';
42→    text?: string;
43→    mimeType?: string;
44→    data?: string;
45→    [key: string]: unknown;
46→  }>;
47→  isError?: boolean;
48→}
49→
50→/**
51→ * Status of an MCP client connection
52→ */
53→export type MCPClientStatus = 'disconnected' | 'connecting' | 'connected' | 'error';
54→
