 32→/**
 33→ * GET /api/collections/[id]/bridge-tools
 34→ * List all bridge tools in a collection
 35→ */
 36→export async function GET(
 37→  _request: NextRequest,
 38→  context: RouteContext
 39→): Promise<NextResponse<ApiResponse>> {
 40→  const requestId = crypto.randomUUID();
 41→  const { id: collectionId } = await context.params;
 42→
 43→  try {
 44→    // Check authentication
 45→    const session = await auth.api.getSession({
 46→      headers: await headers(),
 47→    });
 48→
 49→    if (!session) {
 50→      return NextResponse.json(
 51→        {
 52→          success: false,
 53→          error: { code: 'UNAUTHORIZED', message: 'Authentication required' },
 54→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
 55→        },
 56→        { status: 401 }
 57→      );
 58→    }
 59→
 60→    // Verify collection exists and user owns it
 61→    const collection = await prisma.collection.findUnique({
 62→      where: { id: collectionId },
 63→      include: {
 64→        bridgeTools: {
 65→          orderBy: { createdAt: 'asc' },
 66→        },
 67→        user: {
 68→          include: {
 69→            bridgeConnection: true,
 70→          },
 71→        },
 72→      },
 73→    });
 74→
 75→    if (!collection) {
 76→      return NextResponse.json(
 77→        {
 78→          success: false,
 79→          error: { code: 'NOT_FOUND', message: 'Collection not found' },
 80→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
 81→        },
 82→        { status: 404 }
 83→      );
 84→    }
 85→
 86→    if (collection.userId !== session.user.id) {
 87→      return NextResponse.json(
 88→        {
 89→          success: false,
 90→          error: { code: 'FORBIDDEN', message: 'Access denied' },
 91→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
 92→        },
 93→        { status: 403 }
 94→      );
 95→    }
 96→
 97→    // Get available bridge tools from the user's bridge connection
 98→    interface BridgeTool {
 99→      serverId: string;
100→      serverName: string;
101→      name: string;
102→      description?: string;
103→      inputSchema?: Record<string, unknown>;
104→    }
105→
106→    const availableBridgeTools =
107→      (collection.user.bridgeConnection?.tools as unknown as BridgeTool[]) || [];
108→    const bridgeStatus = collection.user.bridgeConnection?.status || 'disconnected';
109→
110→    // Enrich collection bridge tools with definitions
111→    const enrichedTools = collection.bridgeTools.map((bt) => {
112→      const definition = availableBridgeTools.find(
113→        (t) => t.serverId === bt.serverId && t.name === bt.toolName
114→      );
115→      return {
116→        id: bt.id,
117→        serverId: bt.serverId,
118→        toolName: bt.toolName,
119→        displayName: bt.displayName,
120→        note: bt.note,
121→        createdAt: bt.createdAt,
122→        // Include definition info if available
123→        serverName: definition?.serverName,
124→        description: definition?.description,
125→        available: !!definition && bridgeStatus === 'connected',
126→      };
127→    });
128→
129→    return NextResponse.json({
130→      success: true,
131→      data: {
132→        bridgeTools: enrichedTools,
133→        bridgeStatus,
134→        availableTools: bridgeStatus === 'connected' ? availableBridgeTools : [],
135→      },
136→      meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
137→    });
138→  } catch (error) {
139→    console.error('[API Error] GET /api/collections/[id]/bridge-tools:', error);
140→    return NextResponse.json(
141→      {
142→        success: false,
143→        error: { code: 'INTERNAL_ERROR', message: 'Failed to list bridge tools' },
144→        meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
145→      },
146→      { status: 500 }
147→    );
148→  }
149→}
