 49→/**
 50→ * Find a user by username
 51→ */
 52→async function getUserByUsername(username: string) {
 53→  return withTimeout(
 54→    prisma.user.findUnique({
 55→      where: { username },
 56→      select: { id: true, username: true },
 57→    }),
 58→    DB_TIMEOUT_MS,
 59→    `Database query timed out after ${DB_TIMEOUT_MS}ms`
 60→  );
 61→}
