143→/**
144→ * Extract env vars from request headers.
145→ * Converts headers like `tpmjs-api-key` → `TPMJS_API_KEY`.
146→ */
147→function extractEnvVarsFromHeaders(request: NextRequest): Record<string, string> {
148→  const envVars: Record<string, string> = {};
149→  request.headers.forEach((value, key) => {
150→    if (key.startsWith('tpmjs-')) {
151→      const envKey = key.toUpperCase().replace(/-/g, '_');
152→      envVars[envKey] = value;
153→    }
154→  });
155→  return envVars;
156→}
