 11→/**
 12→ * Bridge Registration & Status API
 13→ *
 14→ * POST: Register bridge tools
 15→ * GET: Get bridge status and pending tool calls
 16→ * DELETE: Disconnect bridge
 17→ *
 18→ * Authentication: Supports both session auth and TPMJS API key auth.
 19→ * Requires 'bridge:connect' scope for API key access.
 20→ */
 21→
 22→// POST: Register bridge and its tools
 23→export async function POST(request: NextRequest) {
 24→  const startTime = Date.now();
 25→  let authResult: Awaited<ReturnType<typeof authenticateRequest>> | null = null;
 26→
 27→  try {
 28→    // Authenticate request (supports both session and API key)
 29→    authResult = await authenticateRequest();
 30→
 31→    if (!authResult.authenticated) {
 32→      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
 33→    }
 34→
 35→    // Check scope for API key auth
 36→    if (authResult.authenticated && !authResult.isSessionAuth) {
 37→      if (!hasScope(authResult, 'bridge:connect')) {
 38→        return NextResponse.json(
 39→          { error: 'API key does not have bridge:connect scope' },
 40→          { status: 403 }
 41→        );
 42→      }
 43→    }
 44→
 45→    // Get user for bridge operations
 46→    const userId = authResult.userId;
 47→    if (!userId) {
 48→      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
 49→    }
 50→
 51→    const body = await request.json();
 52→    const { type, tools, callId, result, error: toolError } = body;
 53→
 54→    if (type === 'register') {
 55→      // Register bridge and tools
 56→      await prisma.bridgeConnection.upsert({
 57→        where: { userId },
 58→        update: {
 59→          status: 'connected',
 60→          tools: tools || [],
 61→          lastSeen: new Date(),
 62→          clientVersion: body.clientVersion,
 63→          clientOS: body.clientOS,
 64→        },
 65→        create: {
 66→          userId,
 67→          status: 'connected',
 68→          tools: tools || [],
 69→          lastSeen: new Date(),
 70→          clientVersion: body.clientVersion,
 71→          clientOS: body.clientOS,
 72→        },
 73→      });
 74→
 75→      // Track usage
 76→      trackUsage({
 77→        apiKeyId: authResult?.apiKeyId ?? undefined,
 78→        userId,
 79→        endpoint: '/api/bridge',
 80→        method: 'POST',
 81→        statusCode: 200,
 82→        latencyMs: Date.now() - startTime,
 83→        resourceType: 'bridge',
 84→      });
 85→
 86→      // Log activity (fire-and-forget)
 87→      logActivity({
 88→        userId,
 89→        type: 'BRIDGE_CONNECTED',
 90→        targetName: 'Bridge',
 91→        targetType: 'bridge',
 92→      });
 93→
 94→      return NextResponse.json({
 95→        success: true,
 96→        message: `Registered ${tools?.length || 0} tools`,
 97→      });
 98→    }
 99→
100→    if (type === 'tool_result') {
101→      // Store tool result for polling
102→      // We use a simple in-memory store for now
103→      // In production, use Redis or similar
104→      const key = `bridge_result:${callId}`;
105→      pendingResults.set(key, { result, error: toolError, timestamp: Date.now() });
106→
107→      return NextResponse.json({ success: true });
108→    }
109→
110→    if (type === 'heartbeat') {
111→      // Update last seen
112→      await prisma.bridgeConnection.update({
113→        where: { userId },
114→        data: { lastSeen: new Date() },
115→      });
116→
117→      return NextResponse.json({ success: true });
118→    }
119→
120→    return NextResponse.json({ error: 'Invalid type' }, { status: 400 });
121→  } catch (error) {
122→    console.error('Bridge POST error:', error);
123→
124→    // Track error
125→    if (authResult?.userId) {
126→      trackUsage({
127→        apiKeyId: authResult?.apiKeyId ?? undefined,
128→        userId: authResult.userId,
129→        endpoint: '/api/bridge',
130→        method: 'POST',
131→        statusCode: 500,
132→        latencyMs: Date.now() - startTime,
133→        resourceType: 'bridge',
134→        errorCode: 'INTERNAL_ERROR',
135→        errorMessage: error instanceof Error ? error.message : 'Internal error',
136→      });
137→    }
138→
139→    return NextResponse.json(
140→      { error: error instanceof Error ? error.message : 'Internal error' },
141→      { status: 500 }
142→    );
143→  }
144→}
