146→// GET: Get pending tool calls (polling)
147→export async function GET(_request: NextRequest) {
148→  try {
149→    // Authenticate request (supports both session and API key)
150→    const authResult = await authenticateRequest();
151→
152→    if (!authResult.authenticated) {
153→      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
154→    }
155→
156→    // Check scope for API key auth
157→    if (!authResult.isSessionAuth && !hasScope(authResult, 'bridge:connect')) {
158→      return NextResponse.json(
159→        { error: 'API key does not have bridge:connect scope' },
160→        { status: 403 }
161→      );
162→    }
163→
164→    const userId = authResult.userId;
165→    if (!userId) {
166→      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
167→    }
168→
169→    // Get pending tool calls for this user
170→    const pendingCalls = Array.from(pendingToolCalls.entries())
171→      .filter(([key]) => key.startsWith(`${userId}:`))
172→      .map(([key, value]) => {
