174→        return value;
175→      });
176→
177→    // Update last seen
178→    await prisma.bridgeConnection.update({
179→      where: { userId },
180→      data: { lastSeen: new Date() },
181→    });
182→
183→    return NextResponse.json({
184→      success: true,
185→      calls: pendingCalls,
186→    });
187→  } catch (error) {
188→    console.error('Bridge GET error:', error);
189→    return NextResponse.json(
190→      { error: error instanceof Error ? error.message : 'Internal error' },
191→      { status: 500 }
192→    );
193→  }
194→}
