196→// DELETE: Disconnect bridge
197→export async function DELETE(_request: NextRequest) {
198→  try {
199→    // Authenticate request (supports both session and API key)
200→    const authResult = await authenticateRequest();
201→
202→    if (!authResult.authenticated) {
203→      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
204→    }
205→
206→    // Check scope for API key auth
207→    if (!authResult.isSessionAuth && !hasScope(authResult, 'bridge:connect')) {
208→      return NextResponse.json(
209→        { error: 'API key does not have bridge:connect scope' },
210→        { status: 403 }
211→      );
212→    }
213→
214→    const userId = authResult.userId;
215→    if (!userId) {
216→      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
217→    }
218→
219→    await prisma.bridgeConnection.update({
