231→
232→    return NextResponse.json({ success: true });
233→  } catch (error) {
234→    console.error('Bridge DELETE error:', error);
235→    return NextResponse.json(
236→      { error: error instanceof Error ? error.message : 'Internal error' },
237→      { status: 500 }
238→    );
239→  }
