### 3. Server-Side MCP Client for Remote Connections

**File: `/Users/ajaxdavis/repos/tpmjs/tpmjs/apps/web/src/lib/mcp/remote-client.ts`** (new file)

This is the core challenge: connecting to remote MCP servers from a serverless environment. The approach is **connect-on-demand with short-lived connections** (no persistent connection pool):

```typescript
import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { StreamableHTTPClientTransport } from '@modelcontextprotocol/sdk/client/streamableHttp.js';
import { SSEClientTransport } from '@modelcontextprotocol/sdk/client/sse.js';

interface RemoteMcpServerConfig {
  url: string;
  authType?: string | null;
  authHeader?: string | null;
  authToken?: string | null;
}

interface RemoteMcpTool {
  name: string;
  description?: string;
  inputSchema?: Record<string, unknown>;
}

/**
 * Connect to a remote MCP server, discover its tools, then disconnect.
 * Stateless - creates and closes a connection each time.
 * Tries StreamableHTTP first, falls back to SSE.
 */
export async function discoverRemoteTools(
  config: RemoteMcpServerConfig
): Promise<RemoteMcpTool[]> {
  const headers: Record<string, string> = {};
  if (config.authType === 'bearer' && config.authToken) {
    headers[config.authHeader || 'Authorization'] = `Bearer ${config.authToken}`;
  } else if (config.authType === 'header' && config.authToken && config.authHeader) {
    headers[config.authHeader] = config.authToken;
  }

  const client = new Client({ name: 'tpmjs-aggregator', version: '1.0.0' });

  // Try StreamableHTTP first, fall back to SSE
  let transport;
  try {
    transport = new StreamableHTTPClientTransport(new URL(config.url), {
      requestInit: { headers },
    });
    await client.connect(transport);
  } catch {
    // Fall back to SSE transport
    transport = new SSEClientTransport(new URL(config.url), {
      requestInit: { headers },
      eventSourceInit: { headers }, // SSE needs headers on initial connection too
    });
    await client.connect(transport);
  }

  try {
    const result = await client.listTools();
    return result.tools.map((t) => ({
      name: t.name,
      description: t.description,
      inputSchema: t.inputSchema as Record<string, unknown>,
    }));
  } finally {
    await client.close().catch(() => {});
  }
}

/**
 * Connect to a remote MCP server, call a tool, then disconnect.
 * Stateless per-call - suitable for serverless.
 */
export async function callRemoteTool(
  config: RemoteMcpServerConfig,
  toolName: string,
  args: Record<string, unknown>
): Promise<{ content: unknown[]; isError?: boolean }> {
  const headers: Record<string, string> = {};
  if (config.authType === 'bearer' && config.authToken) {
    headers[config.authHeader || 'Authorization'] = `Bearer ${config.authToken}`;
  } else if (config.authType === 'header' && config.authToken && config.authHeader) {
    headers[config.authHeader] = config.authToken;
  }

  const client = new Client({ name: 'tpmjs-aggregator', version: '1.0.0' });

  let transport;
  try {
    transport = new StreamableHTTPClientTransport(new URL(config.url), {
      requestInit: { headers },
    });
    await client.connect(transport);
  } catch {
    transport = new SSEClientTransport(new URL(config.url), {
      requestInit: { headers },
      eventSourceInit: { headers },
    });
    await client.connect(transport);
  }

  try {
    const result = await client.callTool({ name: toolName, arguments: args });
    return {
      content: result.content as unknown[],
      isError: result.isError === true,
    };
  } finally {
    await client.close().catch(() => {});
  }
}
```

**Key design decisions**:

- **Connect-per-request**: Since this runs in Vercel serverless, there is no persistent process. Each tool discovery or tool call creates a fresh connection and tears it down. This is slightly slower but reliable in serverless.
- **Dual transport fallback**: Try `StreamableHTTPClientTransport` first (the new standard), fall back to `SSEClientTransport` (deprecated but widely used). This handles both old and new MCP servers.
- **Timeout wrapping**: The callers (API routes) will wrap these in the existing `withTimeout` pattern used throughout the codebase.

---

### 4. Tool Converter Updates

**File: `/Users/ajaxdavis/repos/tpmjs/tpmjs/apps/web/src/lib/mcp/tool-converter.ts`**

Add the `custom` tool type alongside `registry` and `bridge`:

```typescript
