async function handleCustomToolCall(
  collectionId: string,
  serverId: string,
  toolName: string,
  args: Record<string, unknown>,
  requestId: JsonRpcId
): Promise<JsonRpcResponse> {
  // 1. Verify the custom tool exists in the collection
  const collection = await prisma.collection.findUnique({
    where: { id: collectionId },
    include: {
      customTools: {
        where: { server: { id: serverId }, toolName },
        include: { server: true },
      },
    },
  });

  if (!collection?.customTools[0]) {
    return { jsonrpc: '2.0', id: requestId, error: { code: -32602, message: 'Custom tool not found' } };
  }

  const server = collection.customTools[0].server;

  // 2. Call the remote MCP server
  try {
    const result = await callRemoteTool(
      { url: server.url, authType: server.authType, authHeader: server.authHeader, authToken: server.authToken },
      toolName,
      args
    );

    return {
      jsonrpc: '2.0',
      id: requestId,
      result: {
        content: result.content?.length ? result.content : [{ type: 'text', text: 'No content returned' }],
        isError: result.isError,
      },
    };
  } catch (error) {
    return {
      jsonrpc: '2.0',
      id: requestId,
      result: {
        content: [{ type: 'text', text: `Error calling remote MCP server: ${error instanceof Error ? error.message : 'Unknown error'}` }],
        isError: true,
      },
    };
  }
}
