export function sanitizeCustomToolName(serverId: string, toolName: string): string {
  const sanitizedServer = serverId.replace(/[^a-zA-Z0-9_-]/g, '-').slice(0, 20);
  const sanitizedTool = toolName.replace(/[^a-zA-Z0-9_-]/g, '-');
  const fullName = `custom--${sanitizedServer}--${sanitizedTool}`;
  return fullName.slice(0, 64); // MCP 64-char limit
}

